PRAGMA foreign_keys = OFF;
DROP TABLE IF EXISTS characters;
DROP TABLE IF EXISTS units;
DROP TABLE IF EXISTS items;
DROP TABLE IF EXISTS champions;
DROP TABLE IF EXISTS defense_battles;

CREATE TABLE items (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  special_flags TEXT,
  tokusyu TEXT DEFAULT '',
  item_type INTEGER DEFAULT 1,
  power INTEGER DEFAULT 0,
  ammo INTEGER DEFAULT 0,
  en_cost INTEGER DEFAULT 0,
  range_min INTEGER DEFAULT 0,
  range_max INTEGER DEFAULT 0,
  range_short INTEGER DEFAULT 0,
  range_mid INTEGER DEFAULT 0,
  range_long INTEGER DEFAULT 0,
  weight INTEGER DEFAULT 0,
  range_type INTEGER DEFAULT 0,
  special_effect INTEGER DEFAULT 0,
  req_level INTEGER DEFAULT 0,
  price INTEGER DEFAULT 0,
  hit_count INTEGER DEFAULT 1,
  raw_chg TEXT,
  raw_kitai TEXT,
  raw_hani TEXT,
  raw_syurui TEXT,
  raw_soubikin TEXT
);

CREATE TABLE characters (
  id VARCHAR(255) PRIMARY KEY,
  -- password_hash の形式は src/utils/password.ts が唯一の正（pbkdf2$<反復回数>$<salt>$<hash>）。
  -- 旧・無ソルトSHA-256(hex64)の行も login が受け入れ、認証成功時に書き換える。
  --
  -- Google だけで登録した人はパスワードを持たないので '' が入る。
  -- SQLite は既存列の NOT NULL を落とせず、characters.id は30列から参照されているため
  -- テーブル再構築は割に合わない。'' は verifyPassword() が必ず false を返すので、
  -- 「パスワードでのログインが構造的に不可能」という意図どおりの状態になる。
  password_hash VARCHAR(255) NOT NULL,
  -- Google アカウントの sub（このアプリ専用の不変な識別子）。未連携なら NULL。
  -- 要求スコープは openid のみなので、メールアドレスや氏名は受け取らないし保存もしない。
  -- 一意性は下の idx_characters_google_sub で担保する（列に UNIQUE を書くと、
  -- ADD COLUMN しかできない既存DB側と schema が食い違うため）。
  google_sub TEXT,
  handle_name VARCHAR(255) NOT NULL,
  -- email カラムは廃止した（tools/p56_drop_email.sql）。
  -- 登録時に収集していたが、どこからも読まれない書き込み専用の死にカラムであり、
  -- 使わない個人情報を保持し続ける理由が無いため列ごと落とした。
  chara_name VARCHAR(255) NOT NULL,
  status_intuition INTEGER NOT NULL DEFAULT 10,
  status_piloting INTEGER NOT NULL DEFAULT 10,
  status_short_range INTEGER NOT NULL DEFAULT 10,
  status_mid_range INTEGER NOT NULL DEFAULT 10,
  status_long_range INTEGER NOT NULL DEFAULT 10,
  unit_id INTEGER DEFAULT 0,
  weapon_id INTEGER DEFAULT 0,
  item1_id INTEGER DEFAULT 0,
  item2_id INTEGER DEFAULT 0,
  money INTEGER DEFAULT 0,
  exp INTEGER DEFAULT 0,
  level INTEGER DEFAULT 1,
  fame INTEGER DEFAULT 0,
  faction_id INTEGER DEFAULT 0,
  faction_role VARCHAR(50) DEFAULT 'member',
  faction_katagaki VARCHAR(255) DEFAULT '',
  faction_message TEXT DEFAULT '',
  lp INTEGER DEFAULT 0,
  total_battles INTEGER DEFAULT 0,
  win_battles INTEGER DEFAULT 0,
  skills TEXT DEFAULT '',
  traits TEXT DEFAULT '',
  current_hp INTEGER DEFAULT -1,
  current_en INTEGER DEFAULT -1,
  last_battle_at INTEGER DEFAULT 0,
  team_tactic TEXT DEFAULT 'NN',
  unit_custom_hp INTEGER DEFAULT 0,
  unit_custom_en INTEGER DEFAULT 0,
  unit_custom_armor INTEGER DEFAULT 0,
  unit_custom_mobility INTEGER DEFAULT 0,
  unit_custom_sensor INTEGER DEFAULT 0,
  unit_custom_lp INTEGER DEFAULT 0,
  unit_kaisyo INTEGER DEFAULT 0,
  -- 原作 kweight（装備可能重量）。-1 = 未カスタム（units.max_weight をそのまま使う）。
  -- アナハイムのカスタム２（anahaim_act.cgi custmaise_2）でのみ増減する。
  unit_custom_weight INTEGER DEFAULT -1,
  unit_custom_name VARCHAR(255) DEFAULT '',
  tactics TEXT DEFAULT '00',
  nt_level INTEGER DEFAULT 0,
  is_admin INTEGER DEFAULT 0,
  public_comment TEXT DEFAULT '',
  katagaki VARCHAR(255) DEFAULT '',
  icon TEXT DEFAULT '',
  team_notify INTEGER DEFAULT 0,
  battle_comments TEXT DEFAULT '{}',
  awakening_suppressed INTEGER NOT NULL DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE units (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  hp INTEGER DEFAULT 0,
  en INTEGER DEFAULT 0,
  armor INTEGER DEFAULT 0,
  mobility INTEGER DEFAULT 0,
  sensor INTEGER DEFAULT 0,
  max_weight INTEGER DEFAULT 0,
  req_intuition INTEGER DEFAULT 0,
  req_piloting INTEGER DEFAULT 0,
  req_short_range INTEGER DEFAULT 0,
  req_mid_range INTEGER DEFAULT 0,
  req_long_range INTEGER DEFAULT 0,
  req_nt_level INTEGER DEFAULT 0,
  req_fame INTEGER DEFAULT 0,
  terrain_ground INTEGER DEFAULT 0,
  terrain_water INTEGER DEFAULT 0,
  terrain_space INTEGER DEFAULT 0,
  terrain_air INTEGER DEFAULT 0,
  -- 原作 unit_ini 第24フィールド。'##'区切りの複数値（例 '-14##100'）。空文字=特殊能力なし
  tokusyu TEXT DEFAULT '',
  -- 原作 unit_ini 第27フィールド（unit_syurui）。機体種類コードの連結文字列（例 '48Aj'）。
  -- 1文字=1カテゴリのmembership。凡例は utils/unitSyurui の SYURUI_LEGEND（原作 unit_syurui.cgi 相当）。空/'0'=分類なし
  syurui TEXT DEFAULT '',
  custom_cost INTEGER DEFAULT 0,
  unit_lv INTEGER DEFAULT 1,
  special_flags TEXT DEFAULT '',
  image TEXT DEFAULT '',
  price INTEGER DEFAULT 0
);

DROP TABLE IF EXISTS hangars;
CREATE TABLE hangars (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id VARCHAR(255) NOT NULL,
  unit_id INTEGER NOT NULL,
  custom_hp INTEGER DEFAULT 0,
  custom_en INTEGER DEFAULT 0,
  custom_armor INTEGER DEFAULT 0,
  custom_mobility INTEGER DEFAULT 0,
  custom_sensor INTEGER DEFAULT 0,
  custom_weight INTEGER DEFAULT -1,
  custom_lp INTEGER DEFAULT 0,
  kaisyo INTEGER DEFAULT 0,
  current_hp INTEGER DEFAULT -1,
  current_en INTEGER DEFAULT -1,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES characters(id) ON DELETE CASCADE
);

DROP TABLE IF EXISTS item_inventory;
CREATE TABLE item_inventory (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id VARCHAR(255) NOT NULL,
  item_id INTEGER NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES characters(id) ON DELETE CASCADE
);

DROP TABLE IF EXISTS wingmen;
CREATE TABLE wingmen (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  owner_id VARCHAR(255) NOT NULL,
  name VARCHAR(255) NOT NULL,
  unit_id INTEGER DEFAULT 0,
  level INTEGER DEFAULT 1,
  exp INTEGER DEFAULT 0,
  current_hp INTEGER DEFAULT -1,
  current_en INTEGER DEFAULT -1,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (owner_id) REFERENCES characters(id) ON DELETE CASCADE
);

-- P37: 近況ニュース（原作 msvslib.pl kinkyo1-3。結成・優勝などをトップに流す）
DROP TABLE IF EXISTS news;
CREATE TABLE news (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  text TEXT NOT NULL,
  color VARCHAR(32) DEFAULT '',
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

DROP TABLE IF EXISTS events;
CREATE TABLE events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  type VARCHAR(50) NOT NULL,
  message TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

DROP TABLE IF EXISTS battle_logs;
CREATE TABLE battle_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  attacker_id VARCHAR(255) NOT NULL,
  defender_id VARCHAR(255) NOT NULL,
  is_attacker_win INTEGER DEFAULT 0,
  log_text TEXT,
  events_json TEXT,
  meta_json TEXT,
  battle_type TEXT,
  defense_battle_id INTEGER,   -- Q2観戦: 個別戦闘(defense_battles)の作戦への紐付け。作戦ごとの直近戦闘を第三者が観戦するため
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

DROP TABLE IF EXISTS tournaments;
CREATE TABLE tournaments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name VARCHAR(255) NOT NULL,
  description TEXT,
  status INTEGER DEFAULT 0,
  prize_money INTEGER DEFAULT 0,
  participant_limit INTEGER DEFAULT 16,
  entry_fee INTEGER DEFAULT 0,
  host_id VARCHAR(255) DEFAULT NULL,
  -- P33/P39: 大会形式（trmnt_setei.cgi:125-140。0=トーナメント/1=バトルロイヤル/2=シャッフルトーナメント/3=団体総力戦）
  format INTEGER DEFAULT 0,
  -- P39: 1戦毎の恢復（manual_tournament.htm。トーナメント/シャッフルのみ有効）
  heal_between INTEGER DEFAULT 0,
    limit_unit_types VARCHAR(255) DEFAULT '',
    limit_taikyu INTEGER DEFAULT 0,
    limit_taikyu_jyo INTEGER DEFAULT 0,
    limit_undo INTEGER DEFAULT 0,
    limit_undo_jyo INTEGER DEFAULT 0,
    limit_weight INTEGER DEFAULT 0,
    limit_weight_jyo INTEGER DEFAULT 0,
    limit_custom INTEGER DEFAULT 0,
    limit_lv INTEGER DEFAULT 0,
    limit_lv_jyo INTEGER DEFAULT 0,
    limit_rank INTEGER DEFAULT 0,
    limit_rank_jyo INTEGER DEFAULT 0,
    limit_cost INTEGER DEFAULT 0,
    limit_cost_jyo INTEGER DEFAULT 0,
    limit_team_size_1 INTEGER DEFAULT 0,
    limit_team_size_2 INTEGER DEFAULT 0,
    limit_team_taikyu_1 INTEGER DEFAULT 0,
    limit_team_taikyu_2 INTEGER DEFAULT 0,
    limit_team_cost_1 INTEGER DEFAULT 0,
    limit_team_cost_2 INTEGER DEFAULT 0,
    participant_mask INTEGER DEFAULT 0,
    field_terrain INTEGER DEFAULT -2,
    allow_tactics INTEGER DEFAULT 0,
    auto_start_time DATETIME,
    team1_name VARCHAR(255) DEFAULT '',
    team2_name VARCHAR(255) DEFAULT '',
    team1_factions VARCHAR(255) DEFAULT '',
    team2_factions VARCHAR(255) DEFAULT '',
    team_leader INTEGER DEFAULT 0,
    team_tactics INTEGER DEFAULT 0,
    bet_points INTEGER DEFAULT 0,
    team1_allow_free INTEGER DEFAULT 0,
    team2_allow_free INTEGER DEFAULT 0,
    has_special_condition INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    started_at DATETIME,
    finished_at DATETIME
);

DROP TABLE IF EXISTS tournament_participants;
CREATE TABLE tournament_participants (
  tournament_id INTEGER NOT NULL,
  character_id VARCHAR(255) NOT NULL,
  status INTEGER DEFAULT 0,
  -- P33: 団体総力戦の陣営（1 or 2。個人形式は 0）
  side INTEGER DEFAULT 0,
  registered_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (tournament_id, character_id)
);

DROP TABLE IF EXISTS tournament_matches;
CREATE TABLE tournament_matches (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tournament_id INTEGER NOT NULL,
  round_num INTEGER NOT NULL,
  match_index INTEGER NOT NULL,
  fighter1_id VARCHAR(255),
  fighter2_id VARCHAR(255),
  winner_id VARCHAR(255),
  log_text TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- Q5: 大会コメント（tornament.cgi mode=cmnt → trmnt_cmnt）。
-- 原作は大会設定ファイルに「id<>host<>kname<>cmnt<>time」を追記し、大会詳細(trmt_syosai)に名前＋本文を古い順で表示。
-- chara_name はスナップショット（原作 $kname＝キャラクター名を文字列保存＝キャラ削除後も残る挙動に忠実）。
DROP TABLE IF EXISTS tournament_comments;
CREATE TABLE tournament_comments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tournament_id INTEGER NOT NULL,
  character_id VARCHAR(255) NOT NULL,
  chara_name VARCHAR(255) NOT NULL,
  comment TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

DROP TABLE IF EXISTS factions;
CREATE TABLE factions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name VARCHAR(255) NOT NULL,
  leader_id VARCHAR(255) NOT NULL,
  level INTEGER DEFAULT 1,
  influence INTEGER DEFAULT 0,
  color VARCHAR(50) DEFAULT '#ffffff',
  description TEXT,
  funds INTEGER DEFAULT 0,
  max_members INTEGER DEFAULT 30,
  notice TEXT DEFAULT '',
  hp_url VARCHAR(255) DEFAULT '',
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE champions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  type TEXT NOT NULL DEFAULT 'individual',
  champion_id VARCHAR(255) NOT NULL,
  win_count INTEGER DEFAULT 1,
  terrain INTEGER DEFAULT 1,
  terrain_counter INTEGER DEFAULT 10,
  battle_log1 TEXT DEFAULT '',
  battle_log2 TEXT DEFAULT '',
  battle_log3 TEXT DEFAULT '',
  battle_log4 TEXT DEFAULT '',
  battle_log5 TEXT DEFAULT '',
  snapshot_data TEXT,
  def_hp INTEGER,
  def_en INTEGER,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE defense_battles (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  owner_id VARCHAR(255) NOT NULL,
  title TEXT NOT NULL DEFAULT '作戦名未設定',
  is_team INTEGER DEFAULT 0,
  terrain INTEGER DEFAULT 1,
  req_unit_type TEXT DEFAULT '',
  req_max_hp INTEGER DEFAULT 0,
  req_rank INTEGER DEFAULT 0,
  champion_id VARCHAR(255),
  win_count INTEGER DEFAULT 1,
  battle_log1 TEXT DEFAULT '',
  battle_log2 TEXT DEFAULT '',
  battle_log3 TEXT DEFAULT '',
  battle_log4 TEXT DEFAULT '',
  battle_log5 TEXT DEFAULT '',
  snapshot_data TEXT,
  def_hp INTEGER,
  def_en INTEGER,
  last_challenge_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (owner_id) REFERENCES characters(id) ON DELETE CASCADE
);

DROP TABLE IF EXISTS team_members;
CREATE TABLE team_members (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  owner_id VARCHAR(255) NOT NULL,
  character_id VARCHAR(255) NOT NULL,
  snapshot_data TEXT NOT NULL,
  team_tactic TEXT DEFAULT 'NN',
  team_kaisyo INTEGER DEFAULT 0,
  kaisyo_cap INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (owner_id) REFERENCES characters(id) ON DELETE CASCADE
);
-- 同一相手の二重編成を DB 側で禁止（squad.ts の重複チェックの最終防御）
CREATE UNIQUE INDEX IF NOT EXISTS idx_team_members_owner_char ON team_members(owner_id, character_id);

-- 1つの Google アカウントが複数キャラに紐づくのを DB 側で禁止する。
-- 部分索引なので、未連携（NULL）の行がいくつあっても衝突しない。
-- tools/p57_add_google_sub.sql と同一の定義にしてあること（既存DBとの drift 防止）。
CREATE UNIQUE INDEX IF NOT EXISTS idx_characters_google_sub
  ON characters (google_sub) WHERE google_sub IS NOT NULL;

