DROP TABLE IF EXISTS unit_transformations;
CREATE TABLE unit_transformations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  source_unit_id INTEGER NOT NULL,
  target_unit_id INTEGER NOT NULL,
  cost INTEGER DEFAULT 10,
  req_level INTEGER DEFAULT 0,
  req_fame INTEGER DEFAULT 0,
  FOREIGN KEY(source_unit_id) REFERENCES units(id),
  FOREIGN KEY(target_unit_id) REFERENCES units(id)
);

-- P1: 必要名声条件の初期値（seed 機体に req_fame を付与）
UPDATE units SET req_fame = 50 WHERE name = 'ガンダム';
UPDATE units SET req_fame = 200 WHERE name = 'サザビー';

DROP TABLE IF EXISTS chat_messages;
CREATE TABLE chat_messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  character_id VARCHAR(255) NOT NULL,
  faction_id INTEGER DEFAULT 0,
  message TEXT NOT NULL,
  is_faction_only INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (character_id) REFERENCES characters(id) ON DELETE CASCADE
);

DROP TABLE IF EXISTS private_messages;
CREATE TABLE private_messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  sender_id VARCHAR(255) NOT NULL,
  recipient_id VARCHAR(255) NOT NULL,
  message TEXT NOT NULL,
  is_read INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (sender_id) REFERENCES characters(id) ON DELETE CASCADE,
  FOREIGN KEY (recipient_id) REFERENCES characters(id) ON DELETE CASCADE
);

DROP TABLE IF EXISTS bbs_messages;
CREATE TABLE bbs_messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  character_id VARCHAR(255) NOT NULL,
  title VARCHAR(255) DEFAULT '',
  message TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (character_id) REFERENCES characters(id) ON DELETE CASCADE
);

DROP TABLE IF EXISTS market_listings;
CREATE TABLE market_listings (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  seller_id VARCHAR(255) NOT NULL,
  seller_name VARCHAR(255) NOT NULL,
  listing_type VARCHAR(50) NOT NULL, -- 'unit' or 'item'
  target_id INTEGER NOT NULL, -- units.id or items.id
  price INTEGER NOT NULL,
  message TEXT,
  -- P34: オークション（tyuko.cgi + routean.pl。price=最低価格、締切後に落札処理）
  is_auction INTEGER DEFAULT 0,
  deadline_at INTEGER,               -- 締切（unix秒）
  current_bid INTEGER DEFAULT 0,     -- 現在入札額
  current_bidder_id VARCHAR(255),
  current_bidder_name VARCHAR(255),
  price_closed INTEGER DEFAULT 0,    -- 入札額非公開（価格クローズ）
  kaisyo INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (seller_id) REFERENCES characters(id) ON DELETE CASCADE
);

DROP TABLE IF EXISTS faction_units;
CREATE TABLE faction_units (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  faction_id INTEGER NOT NULL UNIQUE,
  unit_id INTEGER NOT NULL,
  custom_name VARCHAR(255) DEFAULT '',
  image VARCHAR(255) DEFAULT '',
  custom_hp INTEGER DEFAULT 0,
  custom_en INTEGER DEFAULT 0,
  custom_armor INTEGER DEFAULT 0,
  custom_mobility INTEGER DEFAULT 0,
  custom_sensor INTEGER DEFAULT 0,
  custom_lp INTEGER DEFAULT 0,
  weapon_id INTEGER DEFAULT 0,
  item1_id INTEGER DEFAULT 0,
  item2_id INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (faction_id) REFERENCES factions(id) ON DELETE CASCADE,
  FOREIGN KEY (unit_id) REFERENCES units(id)
);

INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (0, 'ボール', '一年戦争当時、地球連邦軍が支援用に量産したＭＡ。実際は、軍・民間で使用されていた一般作業用スペースポッドにガンタンクの主砲を改修して搭載したものである。', 150, 175, 16, 30, 40, 8, 0, 0, 10, 0, 0, 0, 0, -3, -3, 2, -2, '', 0, 17, 'RB-79.png', 10);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (1, 'ボール・カスタム', '連邦軍がモビルスーツ支援用として開発した戦闘ポッドボールの先行量産型。一般作業用のスペースポッドに改修を施し、装甲と武装が追加されている。通常型のボールと異なり２連装１８０ミリキャノンを装備している。また、こちらの方が元の作業ポッドの姿をとどめており、ワイヤーぎみっくが搭載されている。', 160, 175, 18, 30, 40, 9, 0, 0, 0, 10, 0, 0, 0, -3, -3, 2, -1, '', 0, 17, 'RB-79K.png', 20);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (2, 'ザクＩ', 'ミノフスキー粒子散布下における戦闘兵器として開発された史上初のＭＳである。この機体の登場が宇宙世紀を変えたと言っても過言ではない。最初のＭＳとはいえ、高い汎用性と有視界戦闘時の性能は従来兵器とは比べ物にならない。大戦末期においても、後方基地や補給部隊に配備され活躍した。', 175, 175, 15, 40, 40, 10, 0, 0, 10, 0, 0, 0, 0, 1, -1, 0, -3, '', 268, 17, 'MS-05.png', 25);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (3, 'ザクタンク', '補給の乏しい前線で考案された、ザクＩＩベースの支援用タンク。ザクの上半身とマゼラアタックのベース部分で構成されている。制式機体ではないため、外観・兵装は戦場によって異なる。', 160, 200, 12, 40, 42, 16, 0, 0, 0, 0, 10, 0, 0, 2, -2, -3, -3, '', 258, 19, 'MS-06V.png', 20);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (4, 'アッグ', '連邦軍基地ジャブロー攻略用に試作された特殊工作用ＭＳ。腕部のドリルと口部のレーザートーチにより地底からのジャブロー進入を実現する。', 245, 225, 18, 50, 42, 12, 0, 20, 30, 0, 0, 0, 0, 2, 0, -3, -3, '4##5', 0, 22, 'EMS-05.png', 100);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (5, 'アッグガイ', '連邦軍基地ジャブロー攻略用に試作された水陸両用ＭＳ。アッガイの派生型で格闘戦能力が向上している。陸戦用ＭＳグフのもつヒートロッドを４本装備し、近接戦闘で高い能力を発揮する。', 300, 200, 21, 40, 48, 10, 10, 20, 30, 0, 0, 0, 0, 0, 2, -1, -1, '4##5', 0, 22, 'MSM-04N.png', 200);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (6, 'ジュアッグ', '連邦軍基地ジャブロー攻略用に試作された水陸両用ＭＳ。アッガイの派生型で砲撃戦能力が向上している。左右腕部の固定武装である３連装３２０ミリロケットランチャーは高い攻撃力を持つ。', 290, 200, 16, 50, 42, 10, 10, 10, 10, 25, 0, 0, 0, 1, 2, -3, -1, '4', 0, 23, 'MSM-04G.png', 150);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (7, 'ザクマリンタイプ', 'ザクＩＩＦ型を水中用に改修した機体。開戦当初、開発が難航していた水陸両用ＭＳに先駆けて暫定的に使用された。急ごしらえの機体であるため、機体性能は高くない。', 290, 225, 20, 40, 42, 11, 0, 20, 0, 30, 0, 0, 0, 0, 4, -4, -2, '5', 0, 24, 'MS-06M.png', 120);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (8, 'グフ', 'ザクＩＩＪ型に代わる主力陸戦ＭＳとして開発された機体。白兵戦を考慮して設計されたため、対ＭＳ戦用の武装が充実しており、ヒートロッドや専用シールド、腕部の固定武装等の特徴的な装備を持つ機体である。', 290, 200, 22, 50, 42, 12, 10, 30, 30, 0, 0, 0, 0, 4, -1, -2, -1, '4', 211, 25, 'MS-07B.png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (9, 'アッガイ', 'ザクＩＩのパーツを流用して開発された低コストの水陸両用ＭＳ。専用の外装塗料による電磁波吸収と機体廃熱の低さからステルス性が高く隠密作戦や偵察に多用された。', 290, 200, 22, 50, 42, 13, 10, 30, 30, 15, 0, 0, 0, 1, 3, -3, -3, '5', 0, 25, 'MSM-04.png', 300);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (10, 'ザクＩＩＦ型', 'ザクＩにかわって量産化されたジオン公国軍の主力となるモビルスーツである。公国軍はこの旧ザクをベースにそれらの問題を解消した新型ＭＳの開発を急いだ。その結果、後に公国軍の主力として活躍することになる名機ＭＳ－０６、ザクＩＩの試作機であるＡ型が完成した。旧ザクにくらべて基本性能がはるかに高く、実戦兵器としてのＭＳはこのザクでほぼ完成されたといってもよいほどである。その完成度の高さから、開発を担当した技術者たちの思考がこのザクからなかなか離れることができなかった。大戦中期まで、公国軍のＭＳがすべてザク系なのはこうした事情もこめられていた。この機体には新型の高出力ジェネレーターが搭載されているため、旧ザクに比べ出力が大幅にアップしているが、その分使用電力も増えたので、旧ザクのような内蔵型ケーブルだけではまかないきれなかった。そのため、一部を機体の外に露出させるタイプの動力パイプが使用されている。', 250, 225, 21, 50, 42, 11, 0, 30, 0, 30, 0, 0, 0, 0, -2, 2, -1, '', 26, 22, 'MS-06F.png', 300);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (11, 'ザクＩＩＪ型', 'ザクＩにかわって量産化されたジオン公国軍の主力となるモビルスーツである。公国軍はこの旧ザクをベースにそれらの問題を解消した新型ＭＳの開発を急いだ。その結果、後に公国軍の主力として活躍することになる名機ＭＳ－０６、ザクＩＩの試作機であるＡ型が完成した。旧ザクにくらべて基本性能がはるかに高く、実戦兵器としてのＭＳはこのザクでほぼ完成されたといってもよいほどである。その完成度の高さから、開発を担当した技術者たちの思考がこのザクからなかなか離れることができなかった。大戦中期まで、公国軍のＭＳがすべてザク系なのはこうした事情もこめられていた。この機体には新型の高出力ジェネレーターが搭載されているため、旧ザクに比べ出力が大幅にアップしているが、その分使用電力も増えたので、旧ザクのような内蔵型ケーブルだけではまかないきれなかった。そのため、一部を機体の外に露出させるタイプの動力パイプが使用されている。また、陸戦用に改良されたバリエーションがこのＪ型である。', 250, 225, 21, 50, 42, 11, 0, 30, 30, 0, 0, 0, 0, 2, -2, 0, 0, '', 210, 22, 'MS-06J.png', 300);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (12, 'デザートザク', 'ザクＩＩＪ型を砂漠戦用に改修した機体。防塵・防砂処理が施されているため、砂漠戦において高い性能を発揮することができる。また、装甲及びジェネレーター出力の強化も図られている。アフリカ戦線において高い戦果を上げた。', 290, 225, 22, 50, 42, 12, 0, 0, 0, 35, 0, 0, 0, 4, -2, -3, -3, '', 396, 25, 'MS-06D.png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (13, 'アクアジム', 'ジムの水中戦用機。公国軍の水中型ＭＳに対抗するために急遽開発されたため、機体バランスが悪く扱いにくい機体である。', 290, 225, 21, 50, 45, 12, 0, 0, 0, 40, 0, 0, 0, 0, 4, -2, -2, '5', 0, 25, 'RAG-79.png', 250);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (14, 'ザクキャノン', 'ザクＩＩＪ型を砲撃戦用に改修した機体。バックパック一体型の１８０ミリキャノン砲を換装することによって、中距離支援能力を獲得している。機体性能は高くないが安価な支援用の機体として活躍した。', 290, 225, 21, 50, 48, 15, 0, 0, 0, 30, 30, 0, 0, 2, -1, 1, 0, '9', 310, 25, 'MS-06K.png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (15, 'ジム', '一年戦争当時、連邦軍が汎用試作型ＭＳであるガンダムをベースに開発した、初の正式な量産型ＭＳ。実際にはガンダムがサイド７でテストを行っていた頃には、すでに第一号機が完成していた。が、にもかかわらず配備が遅れたのはガンダムの実戦稼動データを待っていたためである。連邦軍は、ガンダムの目覚ましい戦績を重視し、当初の予定であった３種類の機体を平行に開発していくという計画を変更し、ガンダムの量産型であるこの機体を主力ＭＳとして量産する方針をうちだした。ガンダムとの最大の違いは、コア・ブロック・システムが破棄されたことである。これは、ＲＸシリーズで想定されていたコアブロックを使用した機体の換装計画が変更になったことや、ガンダムの実戦データの回収によりデータ収集の必要性が無くなったとされたこと、そして、生産性を考慮した結果である。このほか、頭部の形状など、生産性を第一にさまざまな部分の見直しがなされた。装甲も高価で加工のしにくいルナ・チタニウムから従来のチタン合金製に替えられた。武装面では、ガンダムで、威力の高さは認められたもののエネルギー消費量が大きすぎると判断されたビームライフルにかわって、ビームスプレーガンが採用され、ビームサーベルの装備も１本になった。一年戦争末期から量産がありとあらゆる連邦軍基地でおこなわれた。単独で次々と敵機を撃破していったガンダムと違い、数機のジムおよびボールとのフォーメーションによる組織戦を主としていた。このＭＳが大量生産され、次々に戦場に投入されていったおかげで、連邦に勝利をもたらした事実は認めざるをえない。', 240, 250, 21, 50, 42, 11, 0, 10, 30, 30, 0, 0, 0, 1, 0, 0, 0, '', 217, 22, 'RGM-79.png', 250);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (16, 'ゴッグ', '公国軍が開発した水陸両用ＭＳ。水冷式の高出力核融合炉の搭載により、エネルギーＣＡＰ技術を用いることなく、メガ粒子砲の搭載を実現している。陸上移動能力が低いものの、数々の上陸作戦において実績を残した。', 310, 250, 30, 40, 50, 13, 0, 0, 35, 35, 0, 0, 0, 0, 4, -4, -1, '-8##5', 0, 26, 'MSM-03.png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (17, 'ジムコマンド（宇宙仕様）', '大戦後期に生産されたジムの性能向上機。基本設計に大差はないが細かい仕様変更が行われているため、若干だが性能が向上している。', 300, 250, 21, 50, 45, 11, 0, 0, 40, 40, 0, 0, 0, 0, -1, 3, 0, '', 0, 25, 'RGM-79SG.png', 320);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (18, 'ジム・カスタム', '一年戦争後、連邦軍が開発した新型ＭＳ。ジムタイプのＭＳとしては破格の性能をもつ優れた機体である。しかし生産性が低いため、エースパイロット用として少数が生産されただけである。', 300, 250, 21, 60, 58, 12, 0, 0, 40, 40, 0, 0, 0, 2, -1, 0, 0, '', 301, 26, 'RGM-79N.png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (19, '陸戦型ジム', '陸戦型ガンダムのパーツを流用して生産された、ジムの先行量産機。かなりのパーツが陸戦型ガンダム、ひいてはガンダムと同じものを流用しているため、機体性能は高い。', 300, 250, 27, 50, 42, 13, 0, 0, 35, 35, 0, 0, 0, 3, -2, -3, -3, '', 0, 25, 'RGM-79(G).png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (20, 'ジムスナイパーカスタム', 'ジムを熟練パイロット用に改修した機体。狙撃用バイザー、脚部バーニア、大型バックパックの追加により総合性能が向上した。また、ＲＸシリーズ並の威力を有するビームライフルを装備している。', 290, 250, 24, 50, 60, 12, 50, 0, 0, 0, 50, 0, 0, 2, -1, 0, -3, '6', 0, 25, 'RGM-79SC.png', 380);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (21, 'グフ重装型', 'グフに改修を施した重装甲型の機体。改修によって耐久性能が飛躍的に向上し、両腕に５連装マシンガンを装備することで攻撃力が倍増している。反面、機体重量が大幅に増え、運動性が低下してしまった。', 300, 250, 27, 50, 48, 12, 0, 0, 0, 60, 0, 0, 0, 3, -2, -3, -3, '4', 0, 26, 'MS-07C-3.png', 380);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (22, 'ジムキャノン', 'ジムを砲撃戦用として再設計した機体。大量生産されたジムのパーツを約６０％流用することで高い生産性を持つ。肩部キャノン砲の装備に加え装甲の強化が行われている。', 290, 250, 23, 50, 58, 15, 0, 0, 0, 0, 60, 0, 0, 2, 0, 0, 0, '9', 0, 25, 'RGC-80.png', 300);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (23, 'ブルー１号機', 'フラナガン機関所属の科学者クルスト博士が開発した疑似ニュータイプシステム「ＥＸＡＭシステム」を搭載した実験機。陸戦型ガンダムの機体をベースに、ＥＸＡＭシステムを搭載した陸戦型ジムの頭部で構成されている。', 300, 250, 27, 65, 42, 14, 50, 0, 50, 0, 0, 0, 10, 4, -1, 0, 0, '3##4##-103', 0, 28, 'RX-79BD-1.png', 800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (24, '高機動型ザクＩＩ', 'ザクＩＩＦ型を改修した宇宙戦専用機。バックパックの換装と脚部ベクターノズルによって、従来のザクＩＩ系の機体を凌駕する高機動を実現している。しかしメンテナンス面の問題から量産化が見送られた。', 290, 225, 21, 70, 42, 13, 0, 40, 40, 40, 0, 0, 0, 1, -2, 3, 0, '', 118, 27, 'MS-06R1.png', 250);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (25, 'イフリート', 'グフとドムの中間に位置する陸戦用の高性能機。公国軍地球侵攻部隊が独自に開発した機体でゲルググに匹敵する性能を持つが、生産性が低く、８機生産されただけである。', 310, 225, 28, 60, 46, 14, 0, 0, 60, 60, 0, 0, 0, 2, -1, 1, -1, '4', 52, 26, 'MS-08TX.png', 420);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (26, 'ザクＩＩ改', 'ジオン公国の名機、ザクＩＩＦ型の改装型。高機動型ザクＩＩ、ゲルググＪ（イェーガー）と共に「統合整備計画」によって改修された第２期生産型ＭＳ。第２期生産型の中では生産数が多い。主な強化点としては、ジェネレータ出力・推進力の向上、装甲・武装の強化などがあげられる。総推力は改修前の７０％増しになっているが、推進剤の総量は変わらないので、戦闘最大推力時の限界時間は半分に落ちている。データ的には、あのシャア専用機に匹敵する数値を持っているが、一年戦争末期には既に、他の優秀な機体が開発されており、決して高いステータスではない。', 290, 250, 22, 65, 42, 12, 0, 60, 60, 60, 0, 0, 0, 2, -1, 1, 0, '', 0, 26, 'MS-06FZ.png', 250);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (27, 'サイコミュ試験用ザク', 'ザクを用いたＮＴ用ＭＳの試作実験機。初めてサイコミュデバイスが搭載された機体であり、この機体を経て、一年戦争時に投入された最後の機体、ジオングは完成したのである。最高機密であったため「ビショップ」というコードネームが与えられていた。', 300, 275, 24, 50, 54, 12, 50, 50, 0, 0, 50, 1, 0, -3, -3, 1, 0, '2', 0, 26, 'MS-06Z.png', 500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (28, 'パワードジム', '一年戦争終結後、新型ＭＳを開発するために作られたデータ収集用の実験機。大型バックパック及び新型ショックアブソーバーの装備によって他のジムタイプＭＳに比べ、飛躍的に運動性が向上している。', 300, 225, 27, 70, 48, 12, 0, 50, 55, 55, 0, 0, 0, 2, -1, 1, 0, '', 0, 27, 'RGM-79P.png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (29, 'ジム・クゥエル', 'ジム・カスタムと同程度の性能を持つＭＳ。ティターンズが量産機として独自に開発した機体だが、コスト面の問題からエース用として、わずかに生産されただけである。', 310, 250, 25, 60, 52, 12, 0, 0, 60, 60, 0, 0, 0, 2, 0, 2, 0, '', 0, 28, 'RGM-79Q.png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (30, 'ガンタンクＩＩ', 'ガンタンクを局地防衛用の車両として再設計した機体。ＭＳとしては問題点が多かったガンタンクだが、戦闘車両に特化することで問題点を解消し優れた機体に生まれ変わった。', 300, 300, 25, 40, 64, 18, 0, 30, 0, 0, 90, 0, 0, 4, -1, -2, -5, '6', 0, 28, 'RMV-1.png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (31, 'ガンタンク', 'ジオン公国のＭＳ兵器に対抗して計画された連邦軍Ｖ作戦の機体の一つ。長距離砲撃用である。ガンキャノン、ガンダムと並行して製作されたと言われているのが一般的である。キャタピラのため、走破性は高いが地上でのＭＳ戦闘では足元が非常に不安。キャタピラ裏のバーニアノズルを吹かして短時間なら滞空行動も可能。もともとはコアブロックの操縦側、頭部の砲撃側の二人乗りだったが、頭部コクピットから一人でも動かせるように改造された。基本武装は腕部のポップミサイルと肩の１２０ミリ低反動キャノン砲。携行武器を一切持てない点で異例のＭＳと言える。またコア・ブロック・システム採用のため、腰部の旋回の自由度が低い。３機開発されたがサイド７がジオンに強襲を受けた際に２機が大破。１機のみがホワイトベースで運用されていた。ガンダム、ガンキャノンと同じく、ア・バオア・クーでの戦いにおいて大破。', 300, 300, 24, 40, 60, 18, 0, 0, 0, 0, 80, 0, 0, 3, -1, -1, -5, '6##100##-104', 0, 27, 'RX-75.png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (32, 'グフ飛行型', 'グフに改修を施した飛行試験用実験機。ＭＳの陸上運用における最大の問題点、移動能力の遅さを解消すべく開発された機体である。飛行能力の獲得には失敗したものの、ホバー移動による移動性能は良好で陸上での移動速度が向上した。', 325, 250, 25, 60, 48, 12, 0, 60, 0, 80, 0, 0, 0, 1, -3, -3, 4, '', 280, 29, 'MS-07H.png', 400);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (33, '高機動型ザクＩＩ後期型', '高機動型ザクＩＩの後期改良型。公国軍の次期主力ＭＳの候補としてリック・ドムと争った高性能機である。優れた性能を持つ機体だが、量産機としては生産性が低く、リック・ドムに主力ＭＳの座を奪われてしまった。', 290, 250, 21, 80, 42, 13, 0, 65, 65, 65, 0, 0, 0, 1, 0, 3, 0, '', 0, 29, 'MS-06R2.png', 400);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (34, '陸戦型ガンダム', 'ガンダムの陸戦用先行量産型。空間戦闘用の整備を排除し、生産性を高めているが、ガンダムの基本性能はほぼそのまま継承している。機体背部の予備兵装用コンテナにより地上戦での汎用性に優れる。また、この機体はいくつものカスタマイズ機のベースにもなっている。', 315, 300, 32, 50, 48, 15, 75, 75, 75, 75, 0, 0, 10, 4, 0, -3, -1, '', 0, 28, 'RX-79(G).png', 500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (35, 'ブルー２号機', 'ＥＸＡＭシステム搭載実験用に試作されたブルーディスティニーシリーズの２号機。１号機と異なりシステム制御用のリミッターを搭載していないため戦闘能力が極めて高い反面、制御不能の暴走状態に陥るという危険性を秘めている。', 315, 300, 32, 50, 48, 15, 80, 0, 80, 0, 0, 0, 20, 5, 0, 0, -1, '3##4##-103', 0, 30, 'RX-79BD-2.png', 900);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (36, 'ゾゴック', '連邦軍基地ジャブロー攻略用に試作された水陸両用ＭＳ。ズゴックの派生型で格闘戦能力が大幅に向上しているが火器が貧弱なため運用が難しい。', 315, 250, 31, 70, 42, 15, 0, 50, 95, 0, 0, 0, 0, 1, 3, -4, -2, '5', 0, 29, 'MSM-08.png', 400);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (37, 'ザクＩＩＳ型', 'ザクＩＩＦ型をベースに開発され、主にエースパイロットなどに与えられた機体。ジェネレーター出力が約３０％向上しているほか、パーツの８０％以上がＦ型と共通である。優れたパイロットならば、Ｆ型の３倍近い性能を引き出すことも可能であったと言われている。', 290, 250, 30, 60, 50, 11, 0, 0, 0, 100, 0, 0, 10, 0, -1, 3, 0, '4', 0, 27, 'MS-06S.png', 450);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (38, 'サイコミュ高機動試験型ザク', 'サイコミュ試験用ザクに改修を施した試作実験機。高速機動時における有線誘導式ビーム兵器の運用データを得るために開発された。この機体からＮＴ専用機を示す形式ナンバー「ＭＳＮ－０１」が与えられた。', 300, 300, 24, 60, 54, 12, 80, 80, 0, 0, 80, 2, 0, -3, -3, 3, -2, '2', 0, 30, 'MSN-01.png', 700);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (39, 'ガンキャノン量産型', '様々な経緯を経て完成したガンキャノンの量産型。２４０ミリキャノンを２門装備し、装甲も強化された高性能機だったが一年戦争末期に完成したため、性能を発揮することなく終戦を迎えた。', 300, 275, 28, 60, 58, 18, 0, 0, 0, 80, 80, 0, 0, 3, 0, 0, 0, '9', 0, 28, 'RX-77D.png', 340);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (40, 'ガンダイバー', 'アクアジムを再設計しエースパイロット用として強化された機体。基本設計はアクアジムと変わらないが、頭部形状をガンダムに似せているため、水中型ガンダムと呼称されるようになった。', 300, 300, 28, 60, 50, 15, 80, 80, 80, 80, 0, 0, 0, 0, 5, -3, -2, '5', 0, 30, 'RAG-79-G1.png', 400);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (41, 'ドム', '公国軍がザク系のＭＳの設計思想を切り離して開発した初の量産機。熱核ジェットエンジンによるホバー能力は優秀で陸上におけるＭＳの移動速度を飛躍的に向上させた。', 325, 250, 28, 70, 48, 14, 0, 0, 85, 85, 0, 0, 0, 4, -3, 0, -1, '-8', 0, 29, 'MS-09.png', 400);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (42, 'ザクレロ', '初期に試作されたが、想定されたほどの能力が発揮できず、操作不能に陥るなどの理由で実用テスト前に放棄されてしまったＭＡ。しかし、パワーコンデンサが良好でビーム兵器は十分な威力を有していた。', 300, 300, 20, 60, 50, 25, 60, 60, 0, 0, 0, 0, 0, -5, -4, 6, -3, '-8', 546, 31, 'MA-04X.png', 500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (43, 'ドラッツェ', '技術力に乏しいデラーズフリートが開発した突撃戦用ＭＳ。ザク系ＭＳと宇宙戦用攻撃機ガトルのエンジンから再生された。肩部のスラスターポッドと脚部のプロペラント一体型スラスターにより、リック・ドムＩＩに匹敵する高機動を実現している。', 390, 225, 15, 70, 45, 9, 0, 0, 90, 90, 0, 0, 0, 0, -1, 3, 0, '', 0, 28, 'MS-21C.png', 300);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (44, 'ガンキャノン', 'ジオン公国のＭＳ兵器に対抗して計画された連邦軍Ｖ作戦の機体の一つ。中距離支援用ＭＳという設定で、ガンタンク、ガンダムと並行して製作された。より広範囲を視認出来るよう、Ｖ作戦の機体では一番大きなメインカメラを採用している。主な武装は頭部の６０mmバルカンと肩の２４０mmキャノン、そしてガンダムと同じビームライフルを携行している。背面のバーニアノズルを吹かして短時間ではあるが高速ホバー移動が可能。シールドは、装甲が厚い為必要ない、と判断されたため持っていない。機動力・白兵戦能力ではガンダムに劣る。コンセプトとしては良好であったため、本機のコンセプトを受け継ぐジムキャノンなどが生産されていった。', 315, 300, 32, 50, 58, 20, 0, 0, 0, 95, 95, 0, 0, 3, 0, 1, 0, '9##100', 778, 29, 'RX-77.png', 500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (45, 'ズゴック', '公国軍が開発した水陸両用ＭＳ。水冷式冷却システムと空冷式冷却システムを併用することで、陸上でも優れた機動性と運動性を発揮する。陸戦能力が非常に高く数々の上陸作戦において実績を残している。', 325, 300, 28, 60, 42, 16, 0, 0, 95, 95, 0, 0, 0, 2, 3, -3, -1, '4##5', 0, 30, 'MSM-07.png', 400);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (46, 'ジムスナイパーＩＩ', 'ジムスナイパーカスタムの改良機。射撃用のレーザーセンサー及び電子光学式高倍率カメラの装備によって公国軍のゲルググＪＧ（狙撃型）に匹敵する高命中精度を誇る狙撃用の機体。', 315, 300, 25, 60, 70, 12, 100, 0, 0, 0, 100, 0, 0, 3, -2, 1, 0, '6', 0, 31, 'RGM-79SPII.png', 420);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (47, 'リック・ドム', 'ドムを宇宙戦用として改修した機体。スラスターを熱核エンジンからロケットに換装することで空間戦闘を短期間のうちに実現した。宇宙用主力ＭＳの開発が遅延した公国軍が急遽開発した機体だが、優秀な性能を有している。', 350, 250, 28, 70, 48, 14, 0, 0, 90, 90, 0, 0, 0, -1, -3, 4, 0, '-8', 0, 30, 'MS-09R.png', 400);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (48, 'ハイ・ゴッグ', '水陸両用ＭＳ、ゴッグを再設計した後期生産型の機体。「統合整備計画」に伴い改修を受けた。外装は一新され、機関部の換装により機動性が強化され、最大の問題であった陸戦能力が格段に向上している。', 325, 300, 33, 50, 55, 22, 0, 0, 0, 90, 90, 0, 0, 2, 4, -4, -2, '4##5', 862, 31, 'MSM-03C.png', 440);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (49, 'ジムキャノンＩＩ', 'ガンキャノン量産型のデータをフィードバックして完成した、ジムキャノンの後継機。両肩部のキャノン砲をビームキャノンに換装し、格闘戦を想定して左腕にビームサーベルを装備するなど強化が図られている。', 315, 300, 25, 60, 64, 17, 0, 0, 0, 0, 125, 0, 0, 1, -2, 0, 0, '9', 0, 28, 'RGC-83.png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (50, 'グフ・カスタム', 'グフに数々の改修を施した改良型の機体。マシンガン内蔵型の専用マニュピレータの換装、シールドに装着するガトリング砲の追加など、武装が一新されている。グフの格闘性能の高さを継承しつつ射撃性能の向上に成功している。', 300, 300, 30, 75, 50, 12, 0, 0, 125, 0, 0, 0, 0, 5, 0, -4, 0, '4', 291, 31, 'MS-07B3.png', 530);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (51, 'ガンキャノン重装型', 'ガンキャノンを量産化するために試作された機体。コア・ブロック・システムの廃止などのコストダウンが図られたが、ビーム兵器への換装と装甲強化を併せて行ったため生産性は低いため量産化は見送られたが、機体性能はオリジナルのガンキャノンにも劣らなかった。', 315, 325, 34, 50, 64, 22, 0, 0, 0, 0, 130, 0, 0, 3, -2, 0, 0, '9', 0, 29, 'RX-77-3.png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (52, 'イフリート改', 'フラナガン機関所属の科学者クルスト博士が開発した疑似ニュータイプシステム「ＥＸＡＭシステム」を搭載した機体。通常機に比べジェネレーター出力が向上しており、ＥＸＡＭシステムとの相乗効果で飛躍的に性能が向上している。', 315, 300, 30, 70, 48, 15, 100, 0, 90, 90, 0, 0, 20, 3, -1, 0, 0, '3##-103', 0, 29, 'MS-08TX(EXAM).png', 800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (53, 'ギャン', '次期主力ＭＳを決定するコンペンションにおいてゲルググに敗れ、試作機が少数生産された機体。試作機の基本性能を継承し、白兵戦において優れた性能を有している。生産性を高めるため、頭部センサーが排除されている。', 355, 300, 27, 60, 54, 13, 0, 100, 130, 0, 0, 0, 0, 4, -2, 0, 0, '4', 121, 30, 'MS-15A.png', 450);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (54, 'ガンダムＥｚ８', '第０８ＭＳ小隊隊長、シロー・アマダ少尉の陸戦型ガンダムを陸戦型ジムの予備パーツなどを使用して修復した機体。胸部機関砲の廃止と胸部装甲の変更によって耐弾性が上昇した。また、機体の軽量化に伴い機動性が向上している。', 350, 300, 32, 60, 50, 18, 90, 90, 90, 90, 0, 0, 20, 4, -1, -5, 0, '', 0, 31, 'RX-79(G)Ez8.png', 800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (55, 'ギャンキャノン', 'ギャンを改修した中距離支援用の量産機。敵艦隊に突撃を敢行する味方部隊を支援するために開発された機体である。開発を指揮した、ジオン公国マ・クベ大佐の意向により、支援用の機体でありながら格闘戦用のビームサーベルを装備している。', 355, 300, 27, 60, 60, 13, 0, 0, 130, 0, 100, 0, 0, 3, -1, 0, 0, '9', 0, 30, 'MS-15C.png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (56, '高機動型ギャン', 'ギャンに改修を施した高機動型の高性能機。バックパック換装によるジェネレーター出力の強化で機動性が飛躍的に向上している。格闘戦用の新武装ビームランスの装備により圧倒的な格闘戦能力を獲得している。', 355, 300, 27, 70, 54, 13, 0, 100, 130, 0, 0, 0, 0, 2, -2, 2, 0, '4', 0, 31, 'MS-15B.png', 550);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (57, '量産型ゲルググ', '次期主力ＭＳを決定するコンペンションにおいて、ギャンを抑え量産化された機体。初期生産型の基本性能を継承し、量産型として初めてビーム兵器を標準装備し、連邦軍のガンダムに迫る高性能を獲得しているが、投入時期が遅く、パイロットがほとんど学徒動員兵であったため、性能を生かせないことも多く、戦況を変えるまでには至らなかった。', 355, 300, 27, 70, 54, 13, 0, 90, 115, 135, 0, 0, 0, 0, -2, 3, 0, '', 128, 30, 'MS-14A.png', 500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (58, 'ジムＩＩ', '一年戦争時に生産されたジムの改修機。大幅な性能向上はないが、生産性と汎用性が高いため兵器としての完成度は高い。単機の性能ではなく集団で運用したときの性能を評価すべき機体である。以後、この機体をベースにした量産機が多く開発された。', 290, 290, 25, 52, 59, 14, 0, 0, 75, 75, 0, 0, 0, 2, -1, 1, 0, '', 387, 27, 'RMS-179.png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (59, 'ドム・トローペン', '砂漠での運用を考慮したドムの局地戦用改修機。脚部のスラスターインテーク部にダストフィルターを装着することで砂漠を始めとする様々な戦場での運用が可能になっている。', 350, 275, 30, 80, 50, 15, 0, 0, 135, 135, 0, 0, 0, 5, -1, 0, 0, '', 525, 32, 'MS-09F.png', 550);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (60, 'ゲルググキャノン', 'ゲルググを改修した中距離支援用の量産機。敵艦隊に突撃を敢行する味方部隊を支援するために開発された機体である。ビームキャノンの性能は良好で、精鋭部隊「キマイラ」隊を中心に配備された。', 355, 300, 27, 70, 60, 13, 0, 90, 0, 0, 130, 0, 0, 0, -2, 2, 0, '9', 0, 30, 'MS-14C.png', 500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (61, 'ボルジャーノン', 'ルジャーナ領より発掘されたＭＳ、黒歴史（過去の歴史、宇宙世紀など）ではザクＩとザクＩＩと呼ばれていたＭＳである。スエサイド部隊が使用し、隊長であるギャバンがザクＩ（茶色）に搭乗。バズーカ、クラッカーなどを使用。', 250, 225, 21, 50, 42, 11, 0, 30, 30, 0, 0, 0, 30, 2, -2, 0, 0, '', 0, 23, 'MS-05_bol.png', 300);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (62, 'ガンダム・ピクシー', '地球圏戦闘用に開発されたＲＸシリーズ。コア・ブロック・システム及び空間戦闘用装備の排除とアポジモーターの増設により、高い白兵戦能力を獲得。引力圏での瞬発力はガンダムよりも高い。専用武装のビームダガーとサブマシンガンを装備する。', 300, 300, 30, 90, 50, 14, 0, 140, 140, 0, 0, 0, 15, 2, -1, 1, 0, '', 0, 31, 'RX-78XX.png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (63, 'ガルバルディβ', 'ガルバルディαを改修した高性能機。外装の全面的な換装によって機体重量の大幅な軽量化が実現し、運動性が向上した。一年戦争終結後、この機体の性能を評価したティターンズが部分的に改修を施し量産化した。', 380, 300, 30, 60, 55, 16, 0, 125, 125, 125, 0, 0, 0, 0, 0, 2, 0, '', 0, 29, 'RMS-117.png', 800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (64, 'ズゴックＥ（エクスペリメント）', '水陸両用ＭＳ、ズゴッグを再設計した後期生産型の機体。「統合整備計画」に伴い改修を受けた。外装は一新され、機関部の換装により機動性が強化され、陸戦能力が向上している。', 355, 300, 33, 70, 54, 17, 0, 0, 120, 120, 0, 0, 0, 2, 4, -3, -1, '5', 0, 34, 'MSM-07E.png', 500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (65, '高機動型ゲルググ', '少数精鋭のパイロットにより編成された部隊「キマイラ」隊に配備されるために開発された高性能機である。高機動用バックパックの換装、ジェネレーター出力を推力に回すためのビーム兵器の排除により、運動性が飛躍的に向上している。', 355, 300, 27, 80, 54, 13, 0, 145, 125, 125, 0, 0, 0, 0, -2, 4, 0, '', 0, 32, 'MS-14B.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (66, 'ドワッジ', 'ドムの最終量産型の機体。陸戦能力が極めて高く、プロペラントタンクの増設によって、ホバー稼働時間が大幅に延長されている。また、砂漠戦を考慮した防砂処理が機体各所に施されている。', 355, 300, 28, 80, 54, 16, 0, 0, 125, 130, 0, 0, 0, 3, -2, 0, 0, '', 131, 31, 'MS-09G.png', 650);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (67, 'ブルー３号機', 'ＥＸＡＭシステム搭載実験用に試作されたブルーディスティニーシリーズの３号機。基本性能は１、２号機と大差ないが、宇宙仕様に改修されており、空間戦闘においてその真価を発揮する。', 350, 325, 32, 70, 58, 16, 150, 0, 150, 0, 0, 0, 30, 1, -2, 5, -1, '3##4##-103', 0, 35, 'RX-79BD-3.png', 1200);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (68, 'ガンダム', '一年戦争当時、ジオン公国のＭＳ兵器に対抗して計画された連邦軍Ｖ作戦によって生まれた、当時としては脅威的な性能を持つモビルスーツ。超合金ルナ・チタニウム（後のガンダリウム合金の元となったチタン系合金）製の鎧に覆われ、同じくルナ・チタニウム製の盾を持ち、戦艦の主砲並みの威力の小型メガ粒子砲（俗称：ビームライフル）を携行する。また、接近戦・白兵戦能力にも優れ、背面に装備されたビームサーベル、またそれを切り替えたビームジャベリン、追加武装のガンダムハンマー・ハイパーハンマー等を操る。他には携行兵器では最大のハイパーバズーカ、また内蔵武器として６０mmバルカンがよく使用された。Ｖ作戦の機体は本機、ガンダムに加えガンキャノン、ガンタンクが存在するが、このガンダムが最も機動力があり、また汎用性に優れている。背面バーニアを最大出力で吹かすことによってハイジャンプし、少しの間だが滞空することも可能。携行武器の種類の豊富さは他の連邦ＭＳの追随を許さず、大気圏突入能力まで備えている機体。主開発はアムロの父、テム・レイ技術大尉（技術長）が行っていた。製造時の形式番号はガンダーＸ７８。サイド７がジオンのザクに攻撃された際、避難途中のアムロ・レイが偶然マニュアルを発見し、それを見ながらはじめて動かした機体。素人の操縦で新兵と軍曹クラスの操るザクを合わせて２機も破壊したことから、その基本レスポンスの高さが伺える。戦いを重ねる度にデータを蓄積して反応があがっていったようだ。ジオンの赤い彗星ことシャア・アズナブルが素人操縦と解っていても勝てなかった事からもその高性能さがわかる。しかし後半、そんな最新鋭機もアムロの超人的な反応速度（ニュータイプ能力）についには対応しきれなくなる。その後、連邦軍のモスク・ハン博士によって各駆動部にマグネットコーティング処理を施され、一気に機体の反応速度を上げることに成功するのだが、各駆動部がその負荷に耐え切れる保証がない為、結果的にアムロに操縦を萎縮させる結果となってしまった。最終決戦地ア・バオア・クーにおいて、宿敵シャア・アズナブルの操るニュータイプ専用機ジオングと相打ちになり大破、放棄された。しかしコアファイター及びデータは無事連邦技術部に渡されたので、このガンダムが後の連邦軍ＭＳ開発に多大な貢献をしたのは確かであろう。ガンダムは一年戦争中実際３機が製作されたが、サイド７がジオンに強襲されたため、１号機（プロトタイプガンダム）が大破、３号機（Ｇ－３ガンダム）が中破してしまう（この３号機は、後にマグネットコーティング実験機としてルナツーで使われた）。アムロがホワイトベースで使用していたのは２号機であるのは有名な話。またアムロのＮＴ能力を１００％生かす為ＮＴ専用４号機、ガンダムアレックスの開発も行われていた。パワーアップパーツにＧパーツ（Ｇファイター）が存在し、ガンダム各部との組み合わせで状況に応じて装備・仕様を変える事が可能となる。後継機は量産型ジム、陸戦型ガンダムなどの量産型に加えＧＰシリーズ、ＭｋＩＩ等を筆頭に、数限りなくあらゆる時代で製作されている。', 350, 325, 32, 62, 58, 20, 130, 130, 130, 130, 0, 0, 30, 2, 0, 1, 1, '-14##100', 76, 32, 'RX-78-2.png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (69, 'ハイザック', '一年戦争終結後、連邦軍がザクＩＩＦ型を参考に開発した量産型ＭＳ。連邦軍と公国軍の両方の技術を用いることで高性能の獲得が図られたが、中途半端な機体になってしまった。', 400, 300, 29, 70, 55, 15, 0, 0, 0, 100, 0, 0, 0, 0, -1, 0, 0, '', 135, 28, 'RMS-106.png', 750);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (70, 'ガンダムＭｋＩＩ', 'ティターンズ製作のガンダムＭｋＩＩを、エゥーゴが奪い、そのうちの３号機を白く塗り直してエゥーゴの機体とした。エゥーゴがこの機体を奪取したのは、ＭｋＩＩに採用されているムーバブルフレームの技術の入手及び「ガンダム」を奪取し自軍に加えることによりエゥーゴの存在のアピールを図ったためである。こうしてエゥーゴが入手したムーバブルフレームの技術により、エゥーゴもアナハイムエレクトロニクスを通じて可変ＭＳなどの高性能ＭＳの開発が可能となった。この強奪事件はグリプス戦争に火をつけたと同時に、以後のＭＳ開発競争にも火をつけたのである。本編では『Ｚガンダム』でカミーユ・ビダンが物語前半で搭乗した機体である。開発者である両親からデータを盗んでいたため扱いが慣れていたこと、ティターンズからの強奪はカミーユだったこと、エゥーゴのパイロットはリック・ディアスに愛着を持っていたこと、「アムロの再来」としてエゥーゴ上層部がガンダムに乗せたがったこと、などから彼がパイロットに決まったようである。なお、カミーユがパイロットに就任する前には、自分のリック・ディアスをカミーユの父、フランクリン・ビダンに壊されたクワトロ・バジーナことシャア・アズナブルが搭乗していたこともあった。「シャアがガンダムに乗った」この出撃は強烈なインパクトがあった。ただ、ＭＳとしての性能は、開発者のフランクリン・ビダンも言ったように、加速性能以外は決してズバ抜けてはいなかった。このため、ティターンズが後に強力なＭＳを続々開発するにつれ、ニュータイプ能力の発達が目覚ましいカミーユにはこの機体は物足りなくなってきたのである。そこで、新たに開発されたＺガンダムにカミーユが乗り換え、ＭｋＩＩには、元はティターンズでこの機体のテストパイロットをしていたエマ・シーン中尉が乗り継ぐことになった。これに併せて、装甲素材が旧式のチタン合金セラミックであったためその強化とさらなる機動性の向上を図って、サポートメカの Ｇディフェンサーが開発された。これと合体することによりスーパーガンダムとなることが可能である。', 400, 300, 30, 70, 55, 15, 135, 135, 135, 135, 0, 0, 0, 0, -1, 1, 0, '', 302, 29, 'RX-178.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (71, 'ゲルググＪ（イェーガー）', 'マ・クベ中佐（当時）らが立案した「統合整備計画」に基づいて、ゲルググに改修を施した最終量産機である。高精度の照準装置と優れた火器管制システムによる高精度の精密射撃が可能であり、イェガー（猟兵）の名に恥じない性能を持つ。', 360, 300, 27, 80, 72, 14, 0, 155, 100, 155, 0, 0, 0, 0, -2, 4, 0, '', 0, 34, 'MS-14JG.png', 500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (72, 'ゾック', '移動砲台としての役割を担う水陸両用ＭＳ。前後対称の特異な機体形状は運動性の低さを補うためである。９門の偏向メガ粒子砲とフォノンメーザー砲を搭載し、高い火力を誇っている。', 430, 350, 33, 40, 64, 20, 0, 0, 0, 165, 0, 0, 0, -1, 5, -5, -5, '5', 861, 33, 'MSM-10.png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (73, 'Ｇ－３ガンダム', 'グレーに塗装されたガンダムの３号機。ジオン特務部隊のサイド７強襲時に破損した機体だが、ルナツーで修復され、マグネットコーティングの実験機として転用された。そのため運動性は高い。また、小説版『ガンダム』では、アムロがこれに乗って実際に実戦参加、戦闘し、その後戦死している。', 380, 300, 33, 60, 70, 14, 155, 155, 155, 155, 0, 0, 15, 1, -1, 1, 0, '', 0, 31, 'RX-78-3.png', 1400);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (74, 'ギラ・ドーガ', 'ネオジオンの主力モビルスーツ。ザク系モビルスーツの最終発展型とされるが、従来のＭＳに比べ装甲が強化され、機動力が数段アップされている。その性能では同年代の連邦軍の量産機ジェガンを凌駕する。機動性、操作性に優れている割にはコストパフォーマンスが高く、またビームソードアックスやシュツルムファウストなど武器のバリエーションも豊富であった。なお、ニュータイプ専用ＭＳであるヤクト・ドーガは、これをベースに改造された試作機であり、ヤクト・ドーガがＮＴ専用機として高い能力を示せたのは本機、ギラ・ドーガの性能が高かったからである。', 400, 300, 38, 70, 80, 18, 0, 175, 120, 170, 170, 0, 0, 0, -1, 1, 0, '', 360, 32, 'AMS-119.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (75, 'ゲルググマリーネ', '高機動型ゲルググの改修機体。基本的にアポジモーター・プロペラントの増加を行ない、また機体を軽量化させるなどにより、高い機動性をほこる。総合力ではゲルググＪに劣るが量産コストの面で優秀なため、一年戦争後も多く使われた機体である。', 400, 300, 28, 80, 58, 13, 0, 165, 165, 165, 0, 0, 0, 0, -1, 1, 0, '', 137, 31, 'MS-14F.png', 550);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (76, 'フルアーマーガンダム', 'ガンダムに装甲、武装パーツを装着した機体。重武装と耐久力増加を主目的とする。重装甲化の為、やや機動力が犠牲になっている。', 350, 375, 39, 60, 60, 22, 135, 165, 145, 145, 0, 0, 10, 1, -3, 1, 0, '115', 372, 31, 'FA-78-1.png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (77, 'ケンプファー', 'ジオン公国の最終生産モビルスーツ。「ケンプファー」には「闘士」という意味がある。機体は強襲用と分類される特殊機で、全身にスラスターとアポジモーターを大量に配置。それにより高運動性を生み出した。チェーンマインやショットガンなど、この機体ならではの武器も多い。', 360, 350, 33, 80, 58, 18, 0, 0, 165, 165, 0, 0, 0, 3, -1, 1, 0, '', 0, 34, 'MS-18E.png', 800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (78, 'ガンダムアレックス', '一年戦争末期、連邦軍北米オーガスタ基地で開発されたニュータイプ専用ガンダム。全身にマグネットコーティングをほどこし、視認性を向上させるためＭＳでは初の「全周囲モニター」を搭載した機体でもある。増加装甲としてチョバムアーマーを装備可能である。専用武器はビームライフル、ビームサーベル、バルカンに加え腕部に隠されたガトリング砲がある。ニュータイプ能力の肥大したアムロに合わせて作られたが、ジオンの襲撃などによって結局大戦終結までにアムロの手に渡ることはなかった。配備までのメイン・テストパイロットはクリスチーナ･マッケンジー。', 360, 350, 34, 65, 58, 17, 140, 0, 120, 155, 0, 2, 30, 1, -1, 3, 0, '2', 0, 35, 'RX-78NT-1.png', 700);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (79, 'アッザム', '地球の鉱山基地にテストのために設置されていた試作型ＭＡ。ＭＡに分類されているが、実際のところＭＡの兵器概念がまだ漠然としていたため、以後登場するＭＡ群と比べ機動性は劣悪であり浮遊砲台といった方が的を得ている。特筆すべき「ミノフスキークラフトシステム」搭載の面もあまり生かされておらず、同システムの搭載実験機の感は拭えない。ただ、特殊兵装の「アッザムリーダー」が一時的とはいえ、ガンダムの機能を麻痺させた点は特筆すべきであろう。アッザムリーダーの効果はジオン本国ではそれなりに評価されたらしく、ヴァル・ヴァロにリーダー改良型の「プラズマリーダー」が搭載されている。しかし、敵機を確実に撃破できるかどうか疑問な点が残るためか、ヴァル・ヴァロ以後のＭＡ＆ＭＳにリーダータイプの兵器が搭載された事例はない。', 420, 350, 33, 60, 64, 22, 150, 150, 150, 150, 0, 0, 0, 0, -3, -4, 4, '', 0, 34, 'MAX-03.png', 650);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (80, 'リック・ディアス', '初のエゥーゴ用ＭＳ。ガンダリウムγを装甲に使った初のＭＳでもある。開発当初「γガンダム」の名で開発されていたが、公国系技術者が開発を行ったため、ガンダムと異なる形状と名称が与えられた。', 500, 400, 30, 62, 45, 20, 150, 170, 0, 0, 0, 0, 0, 1, -1, 2, 0, '', 0, 34, 'RMS-099.png', 750);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (81, 'マラサイ', 'ハイザックの発展後継機。アナハイム社がティターンズに供給するために生産した機体で、ガンダリウム合金がティターンズのモビルスーツとしては初めて使用されており、ジェネレーターも大幅に向上しているため、性能自体はかなり高い。', 430, 350, 35, 63, 60, 22, 145, 145, 145, 145, 0, 0, 0, 2, -2, 3, 0, '', 307, 35, 'RMS-108.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (82, 'ビグロ', '公国軍が宇宙戦用に開発したＭＡ。ＭＳとは比べものにならない驚異的な運動性と加速性を持つため、対Ｇ耐性の高い者を中心にパイロットが選抜された。大出力メガ粒子砲を始めとする強力な武装を装備する。', 400, 400, 45, 70, 60, 24, 175, 175, 160, 0, 0, 0, 0, -5, -3, 5, -2, '', 0, 37, 'MA-05.png', 680);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (83, 'リ・ガズィ', 'アナハイム・エレクトロニクス社で開発された試作ＭＳ。Ｚガンダムを再設計し、量産化をめざした機体。その名の由来は「Ｒｅｆｉｎｅｄ・Ｇｕｎｄａｍ・Ｚ」の頭文字を取ったものである。高性能ではあるが、かなりの高コストであるＺガンダムを量産に耐えうる物にする為、生産コストを下げ、量産性を高める様開発された機体である。具体的な変更点は、高コストの主な原因である本体に装備されている変形機構を排除し、Ｇディフェンサーに似たバック・ウエポン・システム（ＢＷＳ）を装備する事により宇宙戦闘機に変形するようになっている。', 420, 400, 35, 70, 60, 18, 175, 175, 0, 0, 0, 0, 30, 1, -3, 3, 0, '', 198, 36, 'RGZ-91.png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (84, 'ガンダムＧＰ０１', '連邦軍が、一年戦争から３年、コーウェン准将指揮の元、ガンダムプロジェクトの一環として製造に着手した機体。また、アナハイム社初のガンダムでもある。初代ガンダムのノウハウを活かし、その直系の機体として完成させた。コア・ブロック・システムも残っている。', 465, 350, 33, 63, 60, 18, 150, 175, 175, 175, 0, 0, 20, 3, -1, 0, 0, '101', 87, 34, 'RX-78GP01.png', 750);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (85, 'ガンダムＧＰ０３Ｓ', 'ガンダムＧＰ０３Ｄ「デンドロビウム」のコアとなるガンダム。ＭＳ単体として見ても、オーキスとの合体装置でもある腰部の後ろに装備されたテールバインダーが、ＡＭＢＡＣ機能を果たし、高い機動性を持つ宇宙専用機となっている。', 460, 350, 32, 78, 60, 18, 170, 180, 0, 180, 180, 0, 20, 1, -1, 2, 0, '', 0, 36, 'RX-78GP03S.png', 850);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (86, 'ガンダムＧＰ０２', 'ガンダム試作２号機。核攻撃を自分で行ない、そのまま戦闘空域に突入して闘うことを想定して製作されているため、放射能の遮断に関しては全ガンダム中トップクラスらしい。遮断にはガンダリウム合金が使用されるため、結果的に頑強な装甲を得ることとなった。携行兵器はアトミックバズーカと冷却装置付きシールド。また頭部にはバルカンがある。シールドは核攻撃中の機体温度の上昇を防ぐための意味合いが大きい。またバックパックに核弾頭に関係する装備が集中する為、推進系は肩のアクティブスラスターユニットに集中している。', 465, 350, 33, 55, 60, 22, 180, 180, 180, 0, 180, 0, 50, 3, -1, 2, 0, '', 0, 36, 'RX-78GP02.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (87, 'ガンダムＧＰ０１Ｆｂ', 'アナハイム社が開発したガンダムＧＰ０１は元々地上での戦闘を前提として開発された。それを宇宙での戦闘用にバーニア等を増設し、ＯＳを宇宙用に書き換えた超高機動型宇宙戦用ＭＳ。Ｆｂ（フルバーニアン）と呼ばれる、その全身のバーニアを活かした動きは、デラーズ軍に「バッタ」との愛称を与えさせる程であった。', 465, 350, 33, 80, 60, 18, 180, 180, 180, 180, 0, 0, 40, 0, -3, 3, 0, '102', 0, 36, 'RX-78GP01Fb.png', 850);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (88, 'グラブロ', '公国軍が水陸両用ＭＳと平行して開発した水中用ＭＡ。格闘用のクローは戦艦を一撃で葬り去る威力を持ち、対空、対艦ミサイルを装備しており、水中戦における圧倒的な性能を有している。', 520, 450, 32, 70, 60, 30, 100, 150, 90, 100, 0, 0, 0, -5, 6, -5, -5, '', 0, 41, 'MAM-07.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (89, 'ガンダムＧＰ０４Ｇ', 'ガンダム試作４号機。強襲用として計画された機体。背部に長大なシュツルムブースターとプロペラントタンクを装備しており、敵に高速で突撃して攻撃を加える。両肩の可動式スラスターによって運動性を高めている。主武器として高出力のビームマシンガンを装備する。', 435, 370, 35, 75, 65, 19, 180, 180, 180, 180, 0, 0, 50, 0, 0, 1, 0, '-8', 0, 34, 'RX-78GP04G.png', 850);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (90, 'ガーベラ・テトラ', 'ガンダムＧＰ０４Ｇの試作型として開発されたが、ジオン系の技術者が中心となっていた為、ジオン系の外見を持つ。背部に、シュツルムブースターと２基のプロペラントタンクを装備することにより、戦場に高速で突入できる。両肩に、ショルダーアーマーと一体型の可動式スラスターが装着されている。主武器はビームマシンガン。腕部に２連装の機関砲がある。後にデラーズフリートに譲渡され、愛機ゲルググマリーネを失ったシーマが使用した。', 455, 450, 50, 60, 58, 20, 175, 190, 150, 190, 0, 0, 0, 0, -1, 3, 0, '', 105, 36, 'AGX-04.png', 750);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (91, 'ガブスレイ', 'ティターンズの可変ＭＳ。試作型ながらかなりの性能を持ち、近距離戦・遠距離戦のどちらにでも対応可能である。基本設計はパプティマス・シロッコ。武装としては肩部のメガ粒子砲の他、長い砲身のフェダーインライフルが特徴。', 472, 325, 35, 83, 62, 14, 160, 185, 185, 185, 185, 0, 0, 0, -1, 1, 0, '1', 158, 34, 'RX-110.png', 950);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (92, 'ギャプラン', 'ギャプランのモビルスーツ形態。武装として腰部アーマーの裏に収納されているビームサーベルが使用可能になる。構造が単純なため、この形態への変形はスムーズである。大型ブースターをつけたままでの変形もできる。ムーバブルフレームを使用しない変形ＭＳとしてはかなり優秀な出来だったのではないだろうかと思われる。', 465, 325, 33, 80, 60, 14, 0, 185, 185, 185, 0, 0, 0, 0, -1, 1, 0, '1', 159, 33, 'ORX-005.png', 700);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (93, 'ヴァル・ヴァロ', '一年戦争末期に開発されたモビルアーマー。主兵装として、機首前部に大型メガ粒子砲を内臓しており、出力的にはビグロを上回るものと推定される。副兵装として、ミサイルポッド４門とビームガン２門を搭載。近接戦闘用として、１１０ミリバルカン砲４門、大型クローアーム２機を装備する。フォン・ブラウン在住のジャンクや、ケリィ・レズナーが一機所持し、「星の屑」作戦に際してガンダムＧＰ０１との戦闘となった。', 410, 400, 50, 75, 60, 22, 160, 185, 0, 190, 0, 0, 0, -5, -5, 4, 0, '11', 0, 37, 'MA-06.png', 1300);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (94, 'ブラウ・ブロ', 'サイコミュを搭載したジオン軍のＮＴ専用ＭＡ。 サイコミュで有線式メガ粒子砲をコントロールし、オールレンジ攻撃が可能である。本体は、２基のエンジンブロックと３体の本体モジュールで構成されており、それぞれ分離させることができる。', 425, 400, 25, 50, 75, 30, 175, 0, 0, 0, 170, 2, 0, -5, -4, 3, 0, '2##6##116', 0, 36, 'MAN-03.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (95, 'ジオング', 'ニュータイプ専用機としては初のＭＳ。宇宙専用機であるが設計段階では陸戦用の歩行ユニットが予定されていた。計画では当初ＭＳ－１６の仮ナンバーが付けられていたが、サイコミュ試験用ザクやサイコミュ高機動試験型ザクによるデータ収集が進むうちにＭＳＮ－０２ジオングという正式名称に決定した。ジオングという名称は究極のＭＳにジオン公国の名を冠することにより国民の士気を高めることも考慮に入れて付けられた。', 490, 400, 33, 70, 64, 20, 180, 0, 0, 185, 185, 3, 30, -4, -3, 4, -3, '2##6##103', 101, 41, 'MAN-02.png', 750);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (96, 'Ｚザク', 'Ｚガンダムの頭部が破壊された際に応急処置で浮遊していたザクＩＩの頭を取り付けたもの。全天モニターに慣れた者達に一年戦争当時の視界の狭さはパイロットに恐ろしささえ覚えさせた。', 430, 450, 40, 90, 60, 25, 260, 270, 200, 230, 250, 1, 30, 2, -1, 3, 0, '', 0, 42, 'zzaku.png', 1500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (97, 'ビグザム', 'ジオン軍の大型ＭＡ。対ビームバリアを装備、強力な磁界を発生させる。主力武器となるのが本体中央の大型メガ粒子砲である。本体の周囲に装備された対空メガ粒子砲も強力で、全方位に対して一度に攻撃をすることが可能である。これらの兵器を稼動させるため、４基もの大型熱核反応炉をかかえる。', 500, 500, 64, 40, 60, 50, 130, 200, 0, 120, 205, 0, 40, 0, -1, 2, 1, '7', 0, 38, 'MA-08.png', 700);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (98, 'エルメス', 'ジオン公国で開発されたニュータイプ専用ＭＡ。一年戦争時においてワイヤレス攻撃が可能だった唯一の機体。機体のコントロールから武器の操作まで、すべてサイコミュシステムを利用したコントロール方式がとられている。本体から射出される「ビット」とよばれるサイコミュ兵器十機によって攻撃を行う。ビットによるオールレンジ攻撃ができるエルメスは、接近戦や格闘戦を行う必要が無いのでその形状は極めてシンプルなものになっている。機体下部のスペースは、すべて推進エンジンがしめ、その上部後方はビットの収容スペースである。その前方にコクピットが配され、左右にメガ粒子砲が装備されている。機体全面は、かなり厚めの装甲板で覆われている。宇宙機にしてはバーニアの数が少ないが、これは装甲に弱点を作らないためである。方向転換用バーニアなどをもたない分、機体安定用ジャイロが補助的に作動するようになっている。また、乗員に高Ｇがかからないようにコクピットの周りには高性能緩衝装置がセットされている。その特徴的な姿から連邦軍では「とんがり帽子」とよばれていた。', 475, 400, 31, 60, 99, 30, 200, 150, 0, 0, 185, 2, 20, -4, -3, 5, -1, '2##6##-105', 0, 43, 'MAN-08.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (99, 'アッシマー', '連邦軍が開発した可変モビルアーマー。連邦軍少佐ブラン・ブルタークの愛機として登場した。その固い装甲と素早い変形機能が特徴で、ＭＡからＭＳへの変形時に一瞬だけ隙ができるのが印象的だった。なお、可変ＭＡなので、この形態は本来の姿ではないことになる。ブラン搭乗の機体はエゥーゴ（カラバ）を大いに苦しめ、ロベルトのリック･ディアスを撃墜し、アーガマを撃墜寸前まで追い込んだ。また、この機体の最大の特徴である大気圏内の高速巡航は、かねてより戦場への進出能力拡大を計っていたＭＳ・ＭＡ技術を大幅に飛躍させるきっかけを与えた。', 450, 350, 40, 75, 55, 20, 150, 150, 190, 190, 0, 0, 0, 2, -1, 1, 0, '1', 160, 34, 'MRX-044.png', 850);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (100, 'ハンブラビ', 'パプティマス・シロッコが開発した可変ＭＳ。ガブスレイに比べ変形機構が単純なため量産に適している。また、モノアイを５つ持っているため索敵能力が極めて高い。', 435, 320, 35, 80, 55, 20, 150, 150, 150, 140, 0, 0, 0, 0, -2, 3, 0, '1', 161, 34, 'RX-139.png', 850);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (101, 'パーフェクトジオング', 'ジオングの完成機。開発途中で実戦投入された機体と区別するためパーフェクトジオングと呼ばれる。脚部が完成したことで陸上での行動が可能となり、様々な作戦での運用が可能である。', 499, 400, 40, 80, 64, 25, 185, 0, 0, 185, 185, 3, 50, 0, -1, 2, -1, '2##6##103', 0, 41, 'MSN-02.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (102, 'ガンダムＧＰ０３Ｄ', '連邦によって記録を抹消され歴史の闇に消えた旧型超兵器である。本来拠点防衛用に開発されたらしく、アルビオン艦内に収納する事が出来ないほど巨大であった。戦闘コンテナアームドベースオーキスの中心部にガンダムＧＰ０３Ｓ「ステイメン」を搭載。デンドロビウムがガンダム扱いで中央のステイメンがコアファイターというコンセプトで製作された。', 730, 500, 44, 50, 90, 30, 200, 200, 0, 200, 200, 0, 50, -2, -2, 2, 0, '6##7##113', 0, 44, 'RX-78GP03D.png', 1500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (103, 'ノイエ・ジール', 'デラーズフリートがアクシズから譲り受けた試作ＭＡ。メガ粒子砲を内蔵した腕部によるオールレンジ攻撃が可能だが、サイコミュを搭載していないため、パイロットの負担は大きい。', 480, 499, 40, 60, 60, 28, 160, 200, 185, 185, 190, 0, 30, -3, -1, 3, 0, '7', 0, 38, 'AMX-002.png', 1500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (104, 'ガンダムＭｋＩＩ－ＮＴ', 'ガンダムＭｋＩＩをベースとしてＮＴ用に開発されたＭＳ。しかし、ＮＴ自体数が少ない為、本当のＮＴが搭乗した事はない。その為この機体の実力は未だ未知数である。', 420, 350, 30, 80, 60, 16, 200, 200, 200, 200, 200, 1, 40, 1, -1, 1, 0, '2', 0, 35, 'RX-178-NT.png', 1500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (105, 'ガーベラ・テトラ改', 'ガーベラ・テトラを改修し、機動・運動性を強化した機体。専用装備の強化型ビームマシンガンによって強襲戦能力がさらに向上している。', 465, 400, 33, 90, 65, 16, 0, 205, 205, 205, 205, 0, 50, 0, -1, 4, 0, '-8', 0, 40, 'AGX-04K.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (106, '∀ガンダム', 'イングレッサ領ビシニティ北部のアーク山（マウンテン・サイクル）にある石像「ホワイトドール」より出現。表面は「ナノスキン（自己修復機能をもつ）」という防御材で覆われている。胸の部分はマルチパーパスサイロ（多目的武器庫）となっていて、ミサイルポッド以外にもビームドライブユニットなどに入れ替えが可能なつくりになっている。コクピット部分は分離変形して小型の飛行機になる。', 465, 500, 42, 90, 48, 20, 200, 200, 150, 160, 150, 0, 50, 0, 0, 1, 0, '7##-35##151', 705, 38, 'WD-M01.png', 1500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (107, 'メッサーラ', 'パプティマス・シロッコが開発した可変ＭＡ。高重力の木星圏内での運用を想定し、機体の４０％にも及ぶ大型スラスターを搭載している。全高３０ｍという巨大なサイズを持ちながら、高い機動性を持つ強力な機体である。', 490, 420, 40, 80, 55, 20, 190, 180, 170, 180, 0, 2, 30, -2, -1, 3, 0, '1##2', 162, 40, 'PMX-000.png', 850);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (108, 'バウンド・ドッグ', '強化人間用の可変試作ＭＡ。サイコミュと変形機構の採用により、機体性能が極めて高い。試作機でありながら、３号機まで生産された実績を持つ。', 475, 400, 35, 75, 62, 20, 180, 190, 170, 170, 0, -1, 0, 0, -1, 3, 0, '1##2', 163, 37, 'MRX-055.png', 850);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (109, 'ティターンズ専用ガンダム', 'ティターンズがガンダムＭｋＩＩの開発に先駆けて開発した機体。ベースであるガンダムの限界を超えた性能を引き出したため、稼働時間が短い。', 385, 357, 35, 77, 63, 21, 150, 150, 150, 150, 0, -1, 30, 1, -1, 1, 0, '2##100', 0, 35, 'RX-78T.png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (110, 'ティターンズ専用ハイザック', '一年戦争終結後、連邦軍がザクＩＩＦ型を参考に開発した量産型ＭＳ。連邦軍と公国軍の両方の技術を用いることで高性能の獲得が図られたが、中途半端な機体になってしまった。', 440, 330, 31, 77, 60, 16, 0, 0, 0, 165, 0, 0, 30, 0, -1, 2, 0, '2', 148, 34, 'RMS-106T.png', 750);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (111, 'ティターンズ専用ガンダムＭｋＩＩ', 'ティターンズがグリプスで製作させていた、名機ガンダムの再設計機。この頃の連邦軍およびティターンズのモビルスーツはたいてい旧ジオニックと連邦軍の技術の折衷的なものが多い。代表例が「連邦のザク」ハイザックだが、この機体はほぼ完全に連邦軍系の技術者だけで開発された、まさしくガンダムの直系後継機である。色はティターンズのシンボルカラーである黒を基調としたカラーリングが施されている。武装はビームライフルにハイパーバズーカが基本。バルカンポッドはオプションとして装備できるようになっている。加速性能に優れた汎用型の機体であるが、最大の特徴は初めて装甲内骨格「ムーバブルフレーム」が採用されたということである。これにより、駆動効率を優先した設計が可能となり、ＭＳの運動性能が飛躍的に向上するという発明であった。さらに、この技術は可変ＭＳの開発も促していくことになる。しかし、この機体自体については、フレーム材質に問題があったために試作品３機が製作されただけで量産は中止されたと表向きには言われている。また、後に３機ともエゥーゴに奪われる。', 440, 330, 33, 77, 60, 16, 155, 155, 155, 155, 0, -1, 50, 0, -1, 2, 0, '2', 149, 35, 'RX-178T.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (112, '黒い三連星専用ザクＩ', 'ザクＩの別塗装バージョン。エース部隊「黒い三連星」の搭乗機。黒い三連星がルウム戦役において、レビル将軍を捕らえた時に搭乗していた事で有名な機体である。', 358, 228, 19, 52, 52, 12, 10, 10, 10, 0, 0, 0, 10, 2, -2, 3, 0, '4', 0, 29, 'MS-05(BT).png', 150);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (113, 'ランバ・ラル専用ザクＩ', 'ザクＩの別塗装カスタムバージョン。「青い巨星」の異名を持つランバ・ラルが搭乗し、開戦直後の一週間戦争で４隻以上の戦艦と巡洋艦を撃沈したことで有名な機体である。', 358, 228, 19, 52, 52, 12, 10, 35, 40, 0, 0, 0, 10, 2, -2, 3, 0, '', 0, 29, 'MS-05(RR).png', 150);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (114, 'マ・クベ専用グフ', 'グフに改修を施したカスタムバージョン。作戦参謀マ・クベ大佐の搭乗機。機体性能は一般機と大差はないが、搭乗者の趣味が反映された華美な装飾が施されている。', 377, 260, 28, 65, 54, 14, 0, 40, 40, 0, 0, 0, 20, 4, -2, 0, 0, '', 0, 31, 'MS-07B(MQ).png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (115, 'Ｓ・マツナガ専用ザクＩＩ', 'ザクＩＩＦ型の別塗装カスタムバージョン。「白狼」の異名を持つシン・マツナガの搭乗機。ルウム戦役の功績を認めたドズル中将が贈った機体である。', 377, 293, 27, 65, 54, 13, 0, 0, 0, 30, 0, 0, 20, 0, -1, 3, 0, '', 0, 31, 'MS-06F(SM).png', 300);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (116, 'Ｊ・ライデン専用ザクＩＩ', 'ザクＩＩＦ型の別塗装カスタムバージョン。「紅い稲妻」の異名を持つジョニー・ライデンの搭乗機。ルウム戦役の後に功績が認められて受領した機体である。', 377, 293, 27, 65, 54, 13, 0, 0, 0, 30, 0, 0, 25, 0, -1, 3, 0, '', 0, 31, 'MS-06F(JR).png', 300);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (117, 'シャア専用ザクＩＩ（初期型）', 'シャアが「赤い彗星」という名の由来となった機体。一般にはシャア専用ザクの名で知られている。ザクＩＩＦ型を指揮官や熟練パイロット用にチューンナップした機体。外見的にはボディカラーと指揮官用の「ツノ」が量産型とは異なる。内部的には羊の皮を被った狼と言ったところで、量産型に比べると格段に高性能。エンジン出力が３０％程アップして、プロペラントも増量されている。データ上の性能はＦ型に比べ３０％程度の性能差に過ぎないが、データ以上の性能を発揮、特にシャアの駆るこの機体は、連邦兵士にあたかもノーマル・ザクの数倍の性能を有しているかのごとき錯覚を起こさせた。', 368, 228, 23, 57, 58, 13, 0, 0, 0, 30, 0, 0, 30, 2, -1, 2, 0, '4', 0, 30, 'MS-06(CA).png', 300);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (118, '高機動型ザクＩＩ改良型', '指揮官用の高機動型ザク改良型である。ジオン公国では、指揮官用の機体にツノ状のアンテナをつけることが多い。', 348, 270, 25, 84, 50, 14, 0, 60, 60, 60, 0, 0, 0, 1, -1, 4, 0, '', 0, 33, 'MS-06R1A.png', 800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (119, '黒い三連星専用高機動型ザクＩＩ', '高機動型ザク改良型の別塗装カスタムバージョン。エース部隊「黒い三連星」の搭乗機。', 377, 293, 27, 91, 54, 15, 0, 60, 60, 60, 0, 0, 40, 1, 0, 5, 0, '4', 0, 37, 'MS-06R1(BT).png', 250);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (120, 'Ｓ・マツナガ専用高機動型ザクＩＩ', '高機動型ザク改良型の別塗装カスタムバージョン。「白狼」の異名を持つシン・マツナガの搭乗機。', 377, 293, 27, 91, 54, 15, 80, 60, 60, 60, 0, 0, 40, 1, 0, 5, 0, '', 0, 37, 'MS-06R1(SM).png', 250);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (121, 'ギャン（指揮官機）', '指揮官用のギャンである。性能面で一般機との違いは殆どない。ただし、ジオン公国の伝統として指揮官機には「ツノ」をつける風習があった。これは単なる飾りではなく、部隊機との通信能力向上をかねている。', 426, 360, 32, 68, 64, 14, 0, 160, 160, 0, 0, 0, 20, 3, -1, 0, 0, '', 697, 34, 'YMS-15.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (122, 'Ｊ・ライデン専用高機動型ザクＩＩ後期型', '高機動型ザク後期型の別塗装カスタムバージョン。「紅い稲妻」の異名を持つジョニー・ライデンの搭乗機。', 377, 325, 27, 104, 54, 15, 0, 80, 80, 80, 0, 0, 50, 1, 0, 5, 0, '', 0, 39, 'MS-06R2(JR).png', 400);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (123, 'ニムバス専用ブルー２号機', 'ＥＸＡＭシステムの搭載実験用に試作されたブルーディスティニーシリーズの２号機。ジオン公国軍パイロット、ニムバス・シュターゼンが連邦から奪った後、彼の趣味で肩が赤く塗装された。', 410, 390, 41, 65, 62, 17, 80, 0, 80, 0, 0, 0, 30, 6, -2, -1, 0, '3##-103', 0, 38, 'RX-79BD-2(NS).png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (124, 'ガルマ専用ザクＩＩ', '頭部に近接戦闘用の３０ミリ機関砲を４門装備している。機体自体の性能は、Ｆ型よりも若干チューンアップされている。また、ＦＳタイプはガルマだけに作られたわけでなく、指揮官用として製造されたもので、Ｆ型の生産ラインを利用して製造されている。', 455, 325, 39, 78, 65, 13, 0, 0, 0, 100, 0, 0, 20, 3, 0, 0, 2, '', 0, 38, 'MS-06S(GZ).png', 450);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (125, 'ドズル専用ザクＩＩ', 'ザク指揮官機用の別塗装カスタムバージョン。ザビ家次男、ドズル・ザビ中将の搭乗機である。特徴的な装飾に加えて、専用武器の巨大トマホークを装備したシルエットは連邦軍の兵士達を恐れさせた。', 455, 325, 39, 78, 65, 13, 0, 0, 0, 100, 0, 0, 30, 0, 0, 3, 0, '', 0, 36, 'MS-06S(DZ).png', 450);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (126, 'シャア専用ザクＩＩ', 'ザクＩＩの最終量産型、ザクＩＩ改をシャアの嗜好により赤く塗装した機体。通常の機体に比べ、推進剤を無駄なく有効に使える。また、シャア専用カスタムとして、燃費は悪いが高出力の推進剤が装備されている。ただし、推進剤の搭載量は通常の機体と変わらない。', 455, 325, 39, 78, 65, 13, 50, 100, 0, 100, 0, 0, 50, 2, 0, 4, 0, '4', 0, 39, 'MS-06S(CA).png', 450);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (127, 'ランバ・ラル専用ドム', 'ドムの別塗装カスタムバージョン。「青い巨星」の異名を持つランバ・ラルの搭乗機である。彼に回すことも検討されたドムではあったが、それ以前に戦死してしまったため、結局塗装を通常に戻した上で一般兵へと回されたらしい。', 425, 325, 36, 91, 62, 16, 0, 0, 100, 100, 0, 0, 40, 5, -1, -1, 0, '-8', 0, 38, 'MS-09(RR).png', 400);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (128, 'ゲルググ（指揮官機）', '指揮官型のゲルググである。ジオン公国では、指揮官用の機体に「ツノ」をつけることが多い。', 426, 360, 32, 84, 64, 14, 0, 180, 150, 170, 0, 0, 30, 0, -1, 2, 0, '', 0, 35, 'YMS-14.png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (129, 'シャア専用ズゴック', 'ズゴックの別塗装カスタムバージョン。「赤い彗星」の異名を持つシャア・アズナブルの搭乗機である。ジャブロー潜入時に使用された。', 425, 390, 39, 78, 54, 18, 0, 0, 115, 115, 0, 0, 50, 3, 3, -3, -1, '4', 0, 39, 'MSM-07S(CA).png', 400);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (130, 'シャア専用リック・ドム', 'シャアが搭乗し、彼の嗜好によって赤く塗装されたリック・ドム。ニュータイプ用として開発された高性能機でムサイに匹敵する強力なビームバズーガを装備している。', 455, 325, 36, 91, 62, 16, 0, 0, 120, 120, 0, 0, 40, 2, -2, 4, 0, '4##-8', 0, 40, 'MS-09R(CA).png', 400);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (131, 'ドワッジ改', 'ドワッジを改良したエースパイロット用の高性能機。砂漠戦の名手であるロンメルが搭乗した機体である。肩部のブースターにより機動性が大幅に向上している。また、専用武器のビームカノンは圧倒的な攻撃力を有している。', 426, 360, 33, 96, 64, 17, 0, 0, 145, 145, 0, 0, 0, 4, -1, -1, 0, '', 0, 38, 'MS-09H.png', 650);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (132, 'ランバ・ラル専用ギャン', 'ギャン試作機の別塗装カスタムバージョン。「青い巨星」の異名を持つランバ・ラルの搭乗機である。', 462, 390, 35, 78, 70, 15, 0, 0, 130, 0, 0, 0, 20, 4, -1, 2, 0, '', 0, 40, 'MS-15A(RR).png', 450);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (133, 'ガトー専用ギャン', 'ギャン試作機の別塗装カスタムバージョン。「ソロモンの悪夢」の異名を持つアナベル・ガトーの搭乗機である。', 462, 390, 35, 78, 70, 15, 0, 0, 130, 0, 0, 0, 20, 3, -1, 3, 0, '', 0, 40, 'MS-15A(AG).png', 450);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (134, 'シャア専用ギャン', 'ギャン試作機の別塗装カスタムバージョン。「赤い彗星」の異名を持つシャア・アズナブルの搭乗機である。', 462, 390, 35, 78, 70, 15, 0, 0, 130, 0, 0, 0, 40, 4, -1, 2, 0, '4', 696, 41, 'MS-15A(CA).png', 450);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (135, 'ハイザック・カスタム', 'ハイザックの改造機。バックパックの換装によって、強力な狙撃用ビームランチャーの装備が実現している。また、装甲の強化も施され防御性能も高い。生産数が少ないためか「隠れハイザック」と呼ばれる事もある。', 480, 360, 34, 84, 66, 16, 160, 170, 0, 175, 0, 0, 20, 0, -1, 3, 0, '', 0, 37, 'RMS-106CS.png', 750);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (136, 'スーパーガンダム', 'ガンダムＭｋＩＩと増加装備として開発された戦闘機Ｇディフェンサーが合体した機体。合体により、航続距離、耐久性、ジェネレータ出力の問題が解決している。', 480, 360, 36, 84, 66, 16, 155, 155, 155, 155, 0, 0, 20, 0, -1, 2, 1, '1##108', 446, 37, 'RX-178G.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (137, 'ゲルググマリーネ（指揮官機）', 'ゲルググマリーネに改修を施した海兵隊用の指揮官型高性能機。頭部バルカンの増設、高出力ビームライフルの装備など攻撃力の強化が施されている。', 480, 360, 33, 96, 69, 14, 120, 165, 165, 165, 0, 0, 40, 0, -1, 2, 0, '', 0, 38, 'MS-14Fs.png', 800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (138, 'ランバ・ラル専用ゲルググ', 'ゲルググ初期生産型の別塗装カスタムバージョン。「青い巨星」の異名を持つランバ・ラルの搭乗機。ザクやグフの運用の上で問題となった点などで、野戦指揮官であるラルの提案を取り入れた改修が施された高性能機である。しかし、肝心のこのゲルググが製造に入った段階ですでにラルは戦死しており、この機体のその後の行方は不明である。', 462, 390, 35, 91, 70, 15, 0, 135, 135, 135, 0, 0, 40, 3, 0, 3, 0, '', 0, 42, 'MS-14A(RR).png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (139, 'ガトー専用ゲルググ', 'ゲルググ初期生産型の別塗装カスタムバージョン。「ソロモンの悪夢」の異名を持つアナベル・ガトーの搭乗機。ア・バオア・クー防衛戦で獅子奮迅の活躍を見せ、連邦を恐怖させた機体である。', 462, 390, 35, 91, 70, 15, 0, 135, 135, 135, 0, 0, 40, 0, 0, 3, 0, '', 0, 39, 'YMS-14(AG).png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (140, 'シャア専用ゲルググ', 'ゲルググ初期生産型の別塗装カスタムバージョン。「赤い彗星」の異名を持つシャア・アズナブルが搭乗し、連邦軍のガンダムを中破した機体でもある。', 462, 390, 35, 91, 70, 15, 0, 135, 135, 135, 0, 0, 80, 0, 0, 3, 0, '4##-107', 0, 40, 'MS-14A(CA).png', 350);
