INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (672, 'ガンタンク（ジオン鹵獲機）', 'ジオン軍によって鹵獲されたガンタンクである。しかし、ガンタンクはホワイトベース隊に配備された一機しか存在しないため、実際はこの機体は量産型ガンタンクなどが鹵獲されたものの誤認ではないかとも言われている。', 300, 300, 24, 40, 60, 18, 0, 0, 0, 0, 80, 0, 5, 3, -1, -1, -5, '6##147', 0, 27, 'r_rx75.png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (673, 'ガンキャノン（ジオン鹵獲機）', 'ジオン軍によって鹵獲されたガンキャノンである。ホワイトベース隊に配属された２機は最後まで消息が確認されているため、量産型ガンキャノンの鹵獲機ではないかとも疑われている。', 315, 300, 32, 50, 58, 20, 0, 0, 0, 95, 95, 0, 5, 2, 0, 2, 0, '9##147', 0, 29, 'r_rx77.png', 500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (674, 'ガンダム（ジオン鹵獲機）', 'ジオン軍によって鹵獲されたガンダムである。しかし、ガンダムはホワイトベース隊に配備された一機、サイド７で破壊された一機（プロト）、同じく強襲によって中破し、その後ルナツーでマグネットコーティングの実験機に転用されたもの（Ｇ－３）の３機しか存在しなく、実際はこの機体は陸戦型ガンダムなどの類似した機体が鹵獲されたものの誤認ではないかとも言われている。また、当時ジオン軍は一部の戦線で、鹵獲したジムにガンダムに似た頭部をつけることで、「ジオンにガンダム有り」という恐怖を連邦兵に与える作戦も行っており、それではないかとも言われている。', 350, 325, 32, 62, 58, 20, 130, 130, 130, 130, 0, 0, 5, 2, 0, 1, 1, '4##147', 0, 32, 'r_rx78.png', 600);
