INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (701, 'ガトー専用高機動型ザクＩＩ', '「ソロモンの悪夢」ことアナベル・ガトー用に用意された機体である。ソロモンでリック・ドムに搭乗する前に使っていたと言われている。', 377, 293, 27, 91, 54, 15, 80, 60, 60, 60, 0, 0, 50, 0, -1, 6, -1, '4', 0, 37, 'MS-06R-2(AG).png', 250);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (702, 'シャア専用パーフェクトジオングカスタム', 'ジオングの完成機。開発途中で実戦投入された機体と区別するためパーフェクトジオングと呼ばれる。これはシャア・アズナブル専用として、パーソナルカラーの赤で塗られ、出力を上げている。', 620, 520, 52, 104, 83, 25, 290, 290, 250, 290, 280, 5, 120, 1, -1, 3, 0, '2##6##149', 0, 56, 'MSN-02(PFC)(CA).png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (703, 'Σガンダム', 'デイジェ、ジムＩＩＩと独自のＭＳ開発を進めるカラバであったが、これらＭＳはベースジャパーとの連携無しでは作戦行動がとれず、飛行形態への変形可能なＭＳの開発が急がれた。エゥーゴのＺガンダムの量産化も考えられたが、大気圏内での戦闘力のより優れたＭＳをといった要求から生まれたのがこのΣガンダムであった。エゥーゴの技術援助を得て生まれたそれはＺＺ同様２機の戦闘機に分離でき、両機共にＭＡ形態をとる事も可能な、兵器としてのキャパシティーが非常に高い機体となった。ＭＳ時には複座のメリットを生かして役割分担がなされ、ＡパーツのパイロットはガンナーをＢパーツのパイロットはチーフパイロットを務める。更にＡパーツにニュータイプが乗る場合にはサイコミュ連動の兵装が可能で、搭載能力の大きさと合いまって絶大な攻撃能力を持つ機体である。構造の復雑さ故に量産には不向きながらも、コストパフォーマンスの高さとガンダムを彷彿させるスタイリングから、カラバの象徴的ＭＳとしての活躍が期待されている。', 580, 550, 60, 90, 85, 30, 260, 240, 270, 250, 240, 5, 150, 0, -2, 3, 1, '1##2', 704, 56, '086.png', 3000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (704, 'Σフライヤー', 'Σガンダムの飛行形態である。', 580, 550, 55, 110, 85, 30, 260, 240, 270, 250, 240, 5, 0, -4, -5, 1, 4, '1##2', 703, 55, '087.png', 3000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (705, 'テストベッド・ターンＡガンダム', '∀ガンダムの試作機の１機である。頭部が本機の原型であるターンＸのものに酷似している。このことから、本機のコクピットがこの頭部に置かれていたことがわかる。テストベット・∀ガンダムが建造された時点では、本来のコクピットがデータ収集のためのダミーであることと、テストパイロットを保護するための脱出手段を確保するためという二つの理由から、こうした組み合わせが生まれた。', 465, 500, 42, 90, 48, 20, 200, 200, 150, 160, 150, 0, 50, 0, 0, 1, 0, '7##-35', 0, 38, 'mdl_DG_btatest_1.png', 1500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (706, 'ターンＸ・アーリーアピアレンス', 'ターンＸの試作機の１機である。ターンＸの特徴である分離機能も溶断破砕マニュピレーターもないが、基本的な性能は、ほぼ同等である。', 512, 500, 43, 102, 63, 20, 200, 200, 150, 160, 150, -3, 50, 0, 0, 1, 0, '7##-35', 0, 44, 'mdl_DG_btax_1.png', 1500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (710, 'クワトロ専用Ｚガンダム', 'クワトロ・バジーナ用に製造されたＺガンダム。カミーユが搭乗していたものより機動性がアップしているが、やはりその分頑強さが犠牲になっている。結局実戦に間に合わず、その後のＺバリエーション開発の元機になったとの説もある。', 559, 585, 52, 123, 119, 20, 300, 300, 290, 280, 270, 5, 120, 2, -1, 3, 1, '1##2', 711, 63, 'MSZ-006(CA)_2.png', 2000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (711, 'クワトロ専用ウェイブライダー', 'クワトロ・バジーナ用に製造されたＺガンダム。カミーユが搭乗していたものより機動性がアップしているが、やはりその分頑強さが犠牲になっている。結局実戦に間に合わず、その後のＺバリエーション開発の元機になったとの説もある。', 559, 585, 45, 145, 110, 20, 300, 300, 290, 280, 270, 5, 120, -1, -3, 1, 4, '1##2', 296, 63, 'MSZ-006(CA)WR_2.GIF', 2000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (718, 'ガンダムアクエリアス', 'ＯＺの対モビルドール用試作ＭＳ。エピオンの兄弟機に当たる機体で、対モビルドール用の電子戦装備「アンチＭＤウイルス」を搭載している。ＯＺのトレーズ派によって開発されたが、反トレーズ派によって、開発者と共に闇に葬られた。', 600, 540, 62, 95, 80, 40, 260, 250, 240, 240, 240, -5, 120, 0, -2, 3, 1, '2##4', 0, 55, 'AQUAERIUS.png', 2000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (720, 'ウェイブライダー（アムロ仕様Ｚガンダム）', 'アムロのシンボルカラーの白と青を基調にＺガンダムをカラーリングしたものである。性能は通常のＺガンダムと大差はない。', 430, 450, 40, 115, 95, 20, 280, 280, 280, 270, 260, 4, 120, -1, -2, 3, 3, '1##2', 584, 53, 'amurosiyou-z(MA).png', 2000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (728, '陸戦型ギラ・ドーガ', '再興した新ネオ・ジオン軍の主力量産型機。通常はバック・パックは宇宙用を装備しているが、地上用に換装。重力下での戦闘用に改修された。通常のものとは性能に大差は無い。', 400, 300, 38, 70, 80, 18, 0, 175, 120, 170, 170, 0, 10, 3, 0, 0, -2, '', 0, 35, 'AMS-119E.png', 1500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (729, 'デルタガンダム', '百式のプロトタイプ。当初は変形機能が追加されるはずだったが、設計段階で欠陥が見つかり、変形機能を省略。しかし、そのポテンシャルの高さから「ガンダム」を冠するに相応しい機体として出席したエウーゴ首脳陣を納得させるものであり、コードネーム「δ（デルタ）ガンダム」として正式採用されることが決定した。頭部は、当初ガンダムのものであった。', 450, 420, 35, 85, 100, 25, 200, 210, 160, 160, 160, 0, 120, 3, -1, 3, 0, '4', 0, 47, 'ANAHEIM-TYPE100.png', 2000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (730, 'ガンダムＥｚ８　ヘビーアームドカスタム', '連邦軍のカスタムＭＳ。ガンダムＥｚ８を火力に重点を置いて宇宙用に改造した機体。単機で戦艦並みの高火力を誇る。しかし、機体重量は重く、機動性は高くはない。', 300, 500, 90, 15, 70, 55, 150, 150, 150, 150, 150, 0, 100, 1, -5, 4, -5, '', 0, 37, 'EZ8-HAC.png', 2500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (731, 'ジム・ジャグラー', 'ジオン軍のＮＴ用ＭＡのオールレンジ攻撃に対抗して連邦が独自の技術で開発したオールレンジ攻撃用の機体。サイコミュシステムが開発できず、遠隔誘導攻撃を目的とした擬似的なオールレンジ攻撃を行う。遠隔攻撃ユニットにボールを、メインにはジムを使用している。完成時の記録は残っていない。元々量産機同士をくっつけた継ぎ接ぎであり、完成したとしても性能は低かった。', 350, 600, 20, 45, 45, 30, 120, 160, 140, 140, 130, 0, 50, 1, -2, 1, 0, '', 0, 33, 'GM-jagler.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (732, 'ニムバス専用グフ', 'ニムバス・シュターゼンの専用機を表すカラーリングとして、両肩が赤く塗られたグフ。専用機化にあたり、改造も施されている。しかし、実戦記録は無く、詳細なデータは無い。', 377, 260, 28, 65, 54, 14, 100, 100, 100, 80, 0, 0, 50, 4, 0, -2, 0, '4', 0, 32, 'MS-07B(NS).png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (733, 'レズン専用ゲルググマリーネ', 'ネオ・ジオン軍が保持していたゲルググマリーネをレズン・シュナイダーが自分の専用機として使用。カラーリングも、彼女の専用機を表す青系の色に変わっている。', 520, 390, 36, 104, 75, 16, 0, 165, 165, 165, 0, 0, 75, 0, -2, 4, -2, '4', 0, 44, 'MS-14F(R).png', 1200);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (734, 'ゲルググＪ（イェーガー）グリーン', 'ゲルググＪ（イェーガー）のカラーリングの違うバージョン。ジオン軍の制式カラーの緑に塗装されている。性能は通常のものと変わらない。', 360, 300, 27, 80, 72, 14, 0, 155, 100, 155, 0, 0, 5, 0, -2, 4, 0, '', 0, 34, 'MS-14JG_2.png', 750);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (735, '陸戦型ヤクト・ドーガ', 'ネオ・ジオン軍のＮＴ用ＭＳ、ヤクト・ドーガの地上換装型。元々汎用機のため、交換されたのはバック・パックのみのようである。性能は通常のものと大差は無い。', 475, 375, 40, 90, 58, 30, 180, 140, 150, 160, 0, 0, 20, 3, 0, -1, 1, '', 0, 39, 'MSN-03E.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (736, 'バウンドドックＩＩＩ', '強化人間用の可変試作機、バウンド・ドックの３号機。本当のゲーツ・キャパの専用機という説もある。実戦の記録は無い。', 498, 420, 40, 80, 65, 20, 190, 200, 175, 175, 0, -3, 50, 0, -1, 3, 1, '', 0, 43, 'MRX-055III.png', 2000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (757, 'シュツルム・イェーガー', '地球連邦軍の変形機構を持つ可変ＭＡ。大気圏内を通常の航空機に匹敵するスピードで飛行する事が可能。その機動性を生かし、味方機の掩護や一撃離脱の戦法を得意としている。又、長距離移動や高々度迎撃用に、専用のブースターが用意されている。', 450, 400, 30, 100, 50, 30, 180, 185, 130, 150, 180, 0, 50, 0, -4, 3, 1, '6', 0, 39, 'syutrum-jager.png', 2500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (759, 'シャア専用ザクＩ', 'ザクＩをシャア専用にチューンナップしたものであり、パーソナルカラーである赤で塗られている。しかし、一年戦争開戦当初、まだ彼の実力は認知されておらず、またその特異なマスクもあり、当時は「若造が」などと反感も買ったと言われている。しかしその驚くべき戦果を挙げるにつれ、そのような陰口をたたくものは次第に減っていった。', 240, 200, 20, 62, 55, 10, 0, 100, 100, 80, 0, 0, 20, 1, 0, 0, -1, '4', 0, 23, 'MS-05(CA).png', 300);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (760, 'シーマ専用ザクIIＦ２', '大戦中期以降に量産されたザクＩＩＦ型の改設計機である。それをシーマ・ガラハウのためにチューンナップしたものである。', 375, 320, 32, 75, 60, 14, 85, 120, 120, 100, 0, 0, 50, 1, -2, 3, 0, '4', 0, 34, 'MS-06F2(SG).png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (761, '黒い三連星専用ケンプファー', '先の一年戦争にて偉大な功績を残し、奇しくも戦死をした「黒い三連星」を称え、特別に用意されたケンプファーである。', 468, 455, 42, 104, 75, 18, 0, 200, 200, 200, 0, 0, 50, 3, -1, 2, -2, '4', 0, 45, 'MS-18(BT).png', 800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (762, 'アムロ専用ジム・クゥエル', '連邦のエースパイロットアムロ・レイ専用に手を加えた機体である。しかし、ティターンズが対当し始めた頃から、既にアムロは幽閉状態であり、その後カラバについたことなどから、この機体は実在せず、ティターンズのプロパガンダであっただろうと思われる。', 405, 325, 32, 78, 67, 15, 0, 100, 160, 160, 0, 0, 50, 2, 1, 0, 0, '', 0, 35, 'RGM-79Q(AR).png', 700);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (763, 'Ｚプラスブースターユニット', '各所のフレームがかなり露出しておりそれが大きな特徴。この機体はあくまでＣ１型のバリエーションの一つ。通常型とのパーツ互換は 比較的簡単であろうことが予測できる。四肢の全て、合計４基のＳガンダムのブースターユニットを装備しゼータプラスとＳガンダムの両方のビーム・スマート・ガンを装備する。別名ハミングバードとも呼ばれる。', 450, 470, 40, 85, 80, 17, 210, 200, 180, 210, 170, 1, 100, 0, -2, 4, 1, '1##2', 764, 45, 'MSZ-006C1(Bst).png', 1800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (764, 'Ｚプラスブースターユニット（ＭＡ）', 'Ｚプラスブースターユニットのウェイブライダー形態である。しかし、ＭＳ形態でも十分な機動力が得られるため、この形態での運用は意外と少なかった。', 450, 470, 36, 110, 70, 17, 210, 200, 180, 210, 170, 1, 0, 0, -3, 1, 4, '1##2', 763, 45, 'MSZ-006C1(Bst)(MA).png', 1800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (765, 'アムロ専用ウェイブライダー', 'アムロ専用Ｚガンダムのウェイブライダー形態である。', 500, 585, 25, 150, 119, 20, 280, 280, 280, 270, 260, 4, 120, -1, -2, 3, 3, '1##2', 620, 63, 'MSZ-006(AR1)(MA).png', 2000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (767, 'ティターンズ専用ガルバルディβ', 'ガルバルディαを改修した高性能機。外装の全面的な換装によって機体重量の大幅な軽量化が実現し、運動性が向上した。一年戦争終結後、この機体の性能を評価した連邦軍が部分的に改修を施し量産化した。ティターンズでは、この機体をハイザックと共に運用しようとしていたが連邦軍内部からの反発により実現しなかった。', 460, 350, 38, 68, 60, 20, 150, 150, 150, 150, 0, -1, 25, 1, 0, 2, 0, '', 0, 36, 'RMS-117T.png', 1200);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (776, 'シスクード', '目的のポイントへ高速移動が可能になるよう機動力を極めて高く設計されており、巡航形態への簡易変形を可能としている。極限まで機動力を追求した機体となっているが、燃料とパイロットへの負荷などが問題となり、諸々の問題を解決するため「オフェンスモード」への切り替えを採用している。しかし、パイロットへの負荷が大きすぎるため、ティターンズは実戦投入までオフェンスモードの負荷調整を行う予定だった。その後エゥーゴにより、テスト中に強奪される。', 495, 400, 35, 120, 90, 30, 250, 250, 250, 250, 220, 0, 120, 0, -2, 3, 1, '7', 0, 48, 'LRX-077.png', 2500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (778, 'ガンキャノン１Ａ', 'プロト・タイプが３機製作されており、最終テスト後にホワイト・ベースに配備され、そのデータを基に量産化される予定であった。然し、テスト中にシャア・アズナブル少佐（当時）の部隊と遭遇して部品状態の２機が破壊されており、残った１機のみが暫定的にホワイト・ベースに配備された。ガンキャノンは中距離支援用の為、接近戦用の装備の変わりに厚い装甲を持たせているが、機動力を落とさずに最大の効果を持つ機体が必要とされて、装甲パターンを変更した機体、武装のオプション化等がテストされていた。肩、腕部の装甲、腰部の３連ミサイル・ポッド等が装備された本機もその一例である。', 315, 300, 30, 48, 60, 25, 0, 0, 0, 95, 95, 0, 5, 2, 0, 1, 1, '9', 0, 29, 'RX-77-1A.png', 500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (785, 'ザンジバル改良型', 'ザンジバル級機動巡洋艦の改良型同型艦。大戦末期に製造された試作艦で武装と推力が強化されている。海兵隊が使用していた「リリーマルレーン」が有名である。', 1050, 850, 32, 30, 110, 60, 200, 250, 120, 160, 200, 0, 100, -2, -5, 3, 4, '6', 0, 64, 'ZANZIBALII.png', 11000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (787, 'ハマーン専用リック・ディアス', 'ハマーン・カーンがエゥーゴより提供された機体を試験的に搭乗したものである。このとき、これならエゥーゴと事を構えても問題ないと呟いた。と伝えられるが事実かどうかは定かではない。', 470, 400, 30, 62, 45, 24, 170, 170, 170, 170, 0, 1, 100, 1, -1, 3, 0, '4', 0, 37, 'RMS-099(HK).png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (788, 'ガンダムＭｋＩＩＩイグレイ', '開発途上で生産配備を却下された、ガンダムＭｋＩＩのアドバンスドバージョンである。機体の設計には、汎用性よりもペイロード、出力増強が重視されており、戦術攻撃型モビルスーツに属する機体である。試作のみで終わったが、同キリマンジャロ基地の開発機バイアランが運用されている。', 415, 320, 20, 115, 55, 20, 200, 130, 130, 130, 130, 0, 50, 1, -3, 2, 1, '', 0, 38, 'RX-166.png', 2000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (789, 'ガンダムＭｋＩＩＩハーピュレイ', 'グリプス製で１２番目の試作承認機である、対ゼータガンダム戦用高速可変型モビルスーツ。装甲材強度もガンダリウム・ベータ級の実験機で、装備機能の違いを持つ計３機（１号機フリーア、２号機ハーピュレイ、３号機デュライ）が存在する。２号機ハーピュレイは単体で総ての作戦モードに対応する万能対応型ではなく、その作戦行動にふさわしい装備を選択する装備搭載型機体である。', 420, 320, 20, 100, 75, 20, 200, 150, 150, 0, 0, 0, 50, 0, -3, 3, 1, '', 0, 39, 'RX-272.png', 2000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (790, 'ガンダムＧＰ０１Ｂｓｔ', 'ガンダムＧＰ０１に宇宙用高速ブースターユニットを装着したもの。ＧＰ０３開発の為の基礎研究の一環として作成された。', 480, 380, 38, 100, 55, 25, 160, 180, 180, 180, 150, 0, 30, -5, -4, 5, 1, '101', 0, 42, 'RX-78GP01Bst.png', 800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (791, 'ガンダムＧＰ０１Ｍ', 'ガンダムＧＰ０１に水中用ユニットを装着したものである。', 470, 350, 35, 65, 60, 20, 150, 175, 175, 175, 0, 0, 20, 1, 4, -4, -4, '5##101', 0, 37, 'RX-78GP01M.png', 800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (792, 'ガンダムＧＰ０３Ｂｓｔスプリガン', 'ステイメンの機動力を補うために設計されたタイプである。背中にブースターパックを装備。機動力を補うための案ではあったが、ＧＰ０１Ｆｂの様な機動力ではなく、どちらかというとＧＰ０２のような敵陣深く潜入して中心部を破壊するといった強行突撃型の運用方法を考えて設計された。', 475, 370, 35, 88, 52, 20, 180, 180, 150, 180, 180, 0, 40, 0, -3, 4, 1, '', 0, 39, 'RX-78GP03Bst.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (793, 'ガンダムＮＴ－ＩＩ', 'ガンダムアレックスの戦果から戦後に開発された機体。別にガンダム開発計画が立ち上がったため、このアレックスの系統の開発は中止された。', 380, 380, 30, 85, 65, 20, 160, 140, 140, 150, 0, 2, 30, 1, -1, 4, 0, '2', 0, 40, 'RX-78NT-II.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (802, 'アムロ専用百式', '後世の好事家によって作成された想像ＣＧである。百式のレプリカがこの色に塗られオークションでクワトロ専用百式と共に高値がつけられたそうである。', 500, 430, 45, 100, 75, 28, 180, 180, 180, 180, 180, 0, 80, 2, -1, 3, 0, '', 0, 46, 'MSN-100(AM).png', 2000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (803, 'サザビー・トレーナー', 'ネオ・ジオンパイロットの高性能機体の訓練用に製作された練習機。機動性はサザビーそのものなのだが、サイコフレームや脱出ポッドは取り除かれ、装甲板には低コストのものが使用されているため耐弾性は低く、ファンネルも飾りである。', 400, 380, 30, 95, 50, 25, 180, 190, 180, 180, 180, 0, 30, 0, -3, 1, 1, '', 0, 35, 'MSN-04T.png', 800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (804, 'ギュネイ専用サザビー', '量産型サザビー指揮官機をギュネイのパーソナルカラーの青に塗装し、限界にまで出力を上げた機体である。', 633, 380, 45, 95, 68, 40, 245, 260, 240, 240, 240, -4, 150, 0, -1, 3, 1, '4', 0, 51, 'MSN-04(GG).png', 2500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (805, 'ハマーン専用サザビー', '実は第一次ネオ・ジオン戦争を生き残っていたハマーンが、シャアの反乱時に戦場を駆けた機体。との説があるが、実際はネオ・ジオン辺りのプロバガンダのひとつであろう。', 615, 420, 38, 105, 75, 40, 245, 260, 240, 240, 240, 3, 150, -2, -1, 4, 0, '4', 0, 52, 'MSN-04(HK).png', 2500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (806, '重力下訓練用ザクＩ', '無重力での戦闘経験しかなかったジオン兵の有重力下での戦闘訓練に使用された機体。同時に重力下でＭＳにかかる負荷のテストにも使用された。', 180, 180, 18, 40, 40, 12, 10, 20, 20, 30, 30, 0, 5, 1, -3, 0, -2, '', 0, 18, 'MS-05_2B.png', 120);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (807, 'ノリス・パッカード専用ザクＩＩ', 'たった一機のグフで連邦軍の０８小隊を翻弄する活躍を見せたジオン公国軍のエースパイロット、ノリス・パッカード大佐が搭乗した機体。熟達した戦い方に連邦軍は驚愕したという。', 350, 360, 32, 63, 54, 20, 130, 130, 100, 130, 130, 0, 30, 2, 0, 1, 1, '', 0, 33, 'MS-06F(NP).png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (808, '陸戦型ザクＩＩ改修型', '地上戦用のザクＩＩＪ型の陸戦能力はそのままにし、移動能力の向上を計るため脚部のバーニアを強化するなど若干の改良を加えた機体。少数がこのタイプに改修された。', 270, 250, 25, 55, 45, 20, 30, 50, 50, 30, 30, 0, 15, 4, -2, -2, 0, '', 0, 27, 'MS-06G.png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (810, 'ティターンズ仕様アーガマ', 'エウーゴのアーガマの機動性、戦闘力に注目したティターンズがスウィートウオーターの記録を基に建造したもの。結論としては艦の能力が良いのではなくクルーの能力が優れていた。という事に落ち着き、姉妹艦は建造されなかった。', 1400, 1000, 38, 30, 120, 100, 200, 300, 120, 150, 250, -1, 120, -2, -4, 2, 2, '6', 0, 74, 'argama-T.png', 18000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (811, 'ビグロ長距離航行型', '航続距離を伸ばすことを目的とした機体。ビグロの高速性は航続距離を犠牲にしたものであり、その弱点を克服すべく大型プロペラントタンクと長距離航行用ブースターを装備させた。', 420, 480, 50, 70, 60, 25, 180, 180, 180, 0, 0, 0, 30, -5, -3, 5, -2, '', 0, 40, 'MA-05C.png', 700);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (813, 'ＳガンダムＭｋＩＩ', 'ＳガンダムのＡＬＩＣＥシステムはそのままに機体の基本性能を上げる方向で開発された機体。オプション的な装備は全て外し、基本に立ち戻った設計となっている。', 480, 400, 43, 78, 65, 30, 200, 200, 160, 180, 0, 0, 50, 0, 0, 2, 1, '12##-101##137', 0, 39, 'MSA-0011II.png', 1200);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (814, 'フルアーマーガンダムＭｋＩＩＩ', 'エゥーゴの汎用増加装甲装備型試作ＭＳ。ガンダムＭｋＩＩＩに増加装甲を装備し全般的に性能を向上させた機体。ガンダムＭｋＩＩＩの高機動性を維持するため、スラスター推力を大幅に強化している。またハイパービームキャノンなどの武装が追加され、火力の充実もめざましい。', 475, 420, 60, 86, 75, 32, 210, 200, 180, 180, 150, 4, 40, 2, -3, 3, 0, '2', 0, 47, 'FA-007GIII.png', 2000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (815, 'クロスボーン仕様ガンダムＦ９０ＩＩ', 'クロスボーン・バンガードにて改修したＦ９０ＩＩ。実際にこの機体を運用したわけではなく、その後のＭＳ開発の参考にされた。', 450, 400, 45, 132, 81, 30, 270, 260, 260, 240, 240, 2, 130, 1, -3, 4, 1, '4', 0, 52, 'F90II(XB).png', 2500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (816, 'ガルマ専用ゲルググ', 'ガルマの為に先行して作成されたゲルググ。しかしガルマ戦死のため、再改修を受けシャアに渡された。との皮肉な説がある。', 462, 390, 35, 91, 70, 15, 135, 135, 135, 0, 0, 0, 50, 2, 0, 3, 1, '', 0, 42, 'MS-14A(GZ).png', 350);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (817, 'ガザＧ', 'ガザＥから設計されたガザシリーズのうちのひとつ。ガ・ゾウムとは異なりガザの形状を色濃く残している。', 460, 390, 37, 50, 50, 25, 80, 120, 90, 100, 0, 0, 10, 1, -2, 2, 0, '1', 818, 33, 'AMX-1009.png', 650);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (818, 'ガザＧ（ＭＡ）', 'ガザＧのＭＡ形態である。', 460, 390, 50, 73, 47, 25, 80, 120, 90, 100, 0, 0, 0, -3, -4, 4, 1, '1', 817, 37, 'AMX-1009(MA).png', 650);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (824, 'ガンダムヘイズル', 'ガンダムヘッドを装備することで、視覚的にジオン軍残党に与える心理的影響をテストするために作られた機体である。頭部こそ、“伝説の”ガンダムのそれであるが、ＲＸタイプとして新造されたＭＳではなく、機体のパーツにはジム・クウェルのものが多く使用されている。ただし、基本フレームはジム・クウェルの流用であるが、背部の強化バックパックとそれに付属する可動式ブースター・ポッド、そして脚部の強化スラスターなど機体の各部が運動試験を兼ねた強化パーツに換装されており、その機体のポテンシャルはＲＸタイプに匹敵する。', 450, 400, 40, 88, 77, 30, 150, 180, 160, 140, 0, 0, 100, 2, 0, 1, 0, '', 0, 41, 'RX-121.png', 2000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (826, 'ドダイ（シャアザクＩＩ搭載）', '地球上での戦闘時にシャア専用ザクがドダイに搭載されたもの。しかしながら、シャアが自分のザクをドダイに載せて戦闘した事に関する信用できる記録は残っていない。', 400, 325, 35, 85, 70, 18, 150, 165, 170, 155, 130, 0, 100, 2, -2, -2, 5, '112', 0, 41, 'dodai-MS-06S(CA).png', 1800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (828, 'フォウ専用リック・ディアス', 'カミーユがフォウの懐柔に成功し、エゥーゴ所属になった時に、クワトロ専用リックディアスをフォウ用にカスタム、塗装したもの。さらにカミーユ独自の改造もしたとかしないとか…。以上の説に信憑性はないといわれている。', 470, 420, 30, 68, 79, 20, 150, 170, 0, 0, 0, 0, 30, 1, -1, 2, 0, '', 0, 38, 'RMS-099(FM).png', 750);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (829, 'フォウ専用クィン・マンサ', 'クィン・マンサ開発時のプロトタイプ。操縦者がフォウであったためフォウ専用と言われているが、本当にフォウがテストを行っていたか信頼できる記録には残っていないため、フォウの搭乗を疑問視されることも多い。', 520, 530, 48, 82, 76, 20, 240, 200, 180, 180, 210, 0, 50, 0, -3, 3, 0, '2##7', 0, 44, 'NZ-000(FM).png', 3000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (840, 'ロンメル中佐専用デザートザク', 'アフリカ戦線でロンメル中佐が使用していたとされるＤＣ型。ザクＩＩＵのデザートタイプだがその存在は疑問視されており、この機体はＤ型のカスタム機ではないだろうかと思われる。', 340, 250, 32, 54, 40, 15, 0, 0, 100, 35, 100, 0, 25, 4, -2, -3, -3, '', 0, 28, 'MS-06DRC.png', 500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (841, 'ドム・ゴブリン１号機', '湿地帯専用ドムの別名。ゴブリンズによるもので１号機、２号機がある。', 350, 290, 50, 60, 50, 14, 0, 100, 80, 85, 0, 0, 30, 3, 3, -3, -2, '5', 0, 33, 'MS-09U1.png', 450);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (842, 'ドム・ゴブリン２号機', '湿地帯専用ドムの別名。ゴブリンズによるもので１号機、２号機がある。', 380, 340, 30, 50, 50, 14, 0, 100, 80, 85, 0, 0, 30, 3, 3, -3, -2, '5', 0, 33, 'MS-09U2.png', 450);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (843, 'ゲルググ　サイクロンエッジ壱炎', 'ゲルググのカスタム機。壱炎、弐雷、参風の３種がある。', 510, 450, 65, 80, 70, 25, 300, 200, 200, 180, 150, 0, 40, 3, -2, 1, 0, '', 0, 43, 'MS-14U1.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (844, 'ゲルググ　サイクロンエッジ弐雷', 'ゲルググのカスタム機。壱炎、弐雷、参風の３種がある。', 560, 490, 80, 60, 55, 25, 300, 200, 200, 180, 150, 0, 40, 3, -2, 1, 0, '', 0, 41, 'MS-14U2.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (845, 'ゲルググ　サイクロンエッジ参風', 'ゲルググのカスタム機。壱炎、弐雷、参風の３種がある。', 480, 400, 45, 100, 80, 25, 300, 200, 200, 180, 150, 0, 40, 3, -2, 1, 0, '', 0, 43, 'MS-14U3.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (847, 'キケロガ', 'ニュータイプ専用機体として開発されていたと言われている機体。ＭＳＮ－０１という制式番号は実際には高機動試験用サイコミュ試験型ザクに対して割り当てられたものであり、また公式非公式問わずキケロガに関する情報も非常に少ないことから、採用されたのがＭＳＮ－０１で、このキケロガは不採用となったのではないかと思われる。', 340, 320, 26, 40, 44, 14, 100, 80, 0, 0, 80, 2, 30, -3, -3, 3, -2, '2', 0, 29, 'MSN-01_2.png', 500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (848, '陸戦型ジム・ブルーデッドクロウ', 'マッドドックス１号機、２号機（実際には１号機が２号機で２号機が３号機だった）の隊長機がジオンに回収されてグフ・ファントムの技術をフィードバックしてバックパックを追加し強化した機体。', 400, 360, 34, 78, 50, 20, 150, 180, 150, 100, 0, 0, 50, 5, -1, -4, -3, '4', 0, 36, 'RGM-79(G)BDC.png', 750);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (851, 'リド・ウォルフ専用ジム・スナイパーＩＩ', '「踊る黒い死神」の異名で公国軍に恐れられた彼の乗機。地上ではガンキヤノン量産型、ジム・キャノン、宇宙ではジム・スナイパーＩＩに搭乗したと見られている。　どれも黒く塗られており､機体を激しく動きまわらせることから《踊る黒い死神》の異名を与えられた。ちなみに、乗機の塗装と戦法の特徴は彼の戦闘機時代からのものであったという。', 405, 290, 23, 64, 60, 14, 100, 120, 0, 0, 100, 0, 50, 2, -2, 3, 0, '6', 0, 34, 'RGM-79SP(RW).png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (852, 'リド・ウォルフ専用量産型ガンキャノン', '「踊る黒い死神」の異名で公国軍に恐れられた彼の乗機。地上ではガンキヤノン量産型、ジム・キャノン、宇宙ではジム・スナイパーＩＩに搭乗したと見られている。　どれも黒く塗られており､機体を激しく動きまわらせることから《踊る黒い死神》の異名を与えられた。ちなみに、乗機の塗装と戦法の特徴は彼の戦闘機時代からのものであったという。', 410, 275, 30, 60, 58, 18, 0, 130, 0, 80, 80, 0, 50, 4, 0, 0, 0, '9', 0, 33, 'RX-77D(RW).png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (859, 'ＥＸ－Ｗガンダムゼロカスタム', '五体のガンダムを開発した五博士が、１５年前「すべてのＭＳの原型」トールギスを発展させ設計した最初にして最強のガンダム。そのガンダムをさらに改良したもの。コクピットに搭載された「ゼロシステム」と呼ばれる戦闘補助システムは戦闘中に得られる膨大な未来予測データのすべてをパイロットの頭脳へ直に流し込むことで「未来を見せる」このシステムでパイロットの戦闘能力を爆発的に増強すると同時にその精神に並ならぬ負担をかける。', 590, 600, 70, 90, 70, 30, 300, 300, 300, 300, 300, -5, 100, 1, -1, 3, 3, '10##-43', 0, 58, 'Ex_wzero_cus.png', 15000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (860, 'フルアーマーＺＺガンダム最終実験機', 'ＺＺガンダムの「フルアーマー計画」で製作された実験機。この機体は第一次ネオ・ジオン紛争で使用されたものではなく、フルアーマーＺＺの実験機である。ＦＡＺＺの生産後に製作された最終実験機となる。外観こそＺＺガンダムとにているものの、サイコガンダムなどのノウハウが転用され、まったくの新型機として生産されており、全長が３０ｍを超える大型ＭＳと化している。', 600, 520, 80, 42, 45, 30, 220, 200, 200, 200, 230, 3, 25, 1, -1, 2, 0, '2', 0, 42, 'FA-010E.png', 1500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (861, 'ゾック改', '移動砲台としての役割を担う水陸両用ＭＳ。運動性の低さを解消するため、徹底した改修が行われている。両手にある砲門は武器ではなくハイドロジェットであるが、戦闘時には近接用武器としても使用された。', 390, 420, 25, 58, 66, 25, 0, 50, 0, 165, 150, 0, 5, 1, 5, -5, -5, '5', 0, 37, 'MSM-10(kai).png', 800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (862, 'ハイ・ゴッグ改', 'さらに地上での機動性が強化され、陸戦能力の向上を図った機体。その分水中での機動性は犠牲となったが、結果的にはバランスの良いものとなった。', 300, 300, 25, 70, 55, 20, 0, 100, 0, 90, 90, 0, 5, 3, 3, -4, -2, '4##5', 0, 32, 'MSM-03C(kai).png', 500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (863, 'ガンダムＭｋＩＩ改', 'ガンダムＭｋＩＩの改修型のうちのひとつ。防御面の強化を図ったものであるが、フルアーマー方式の方が優れていると、テスト段階で開発は中止された。', 460, 360, 62, 70, 50, 18, 135, 150, 120, 180, 0, 0, 0, 0, -1, 1, 0, '', 0, 33, 'RX-178R.png', 1200);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (864, 'プロトタイプガンダムアレックス', 'ガンダムアレックスのプロトタイプ。別に計画のあったヘビーガンダムが設計の基となっていて、アーマーの機体脱着は考慮されていない。結局、より応用の利くチョバムアーマーへと設計は修正された。', 350, 420, 60, 54, 60, 24, 140, 160, 120, 155, 0, 1, 20, 2, -1, 2, 0, '2', 0, 36, 'RX-78NT-P.png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (865, 'キュベレイ改', 'キュベレイに大気圏内の運用を考え変形機構を持たせたもの。その他の能力はキュベレイと大差はない。', 550, 500, 45, 100, 80, 26, 250, 200, 205, 210, 215, 5, 50, 3, -1, 1, 0, '1##2', 866, 52, 'AMX-004(kai).png', 3000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (866, 'キュベレイ改（ＭＡ）', 'キュベレイに大気圏内の運用を考え変形機構を持たせたもの。その他の能力はキュベレイと大差はない。', 550, 500, 40, 105, 80, 26, 250, 200, 205, 210, 215, 5, 50, -1, 2, 1, 3, '1##2', 865, 54, 'AMX-004(kai)(MA).png', 3000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (869, 'シャア専用グフフライトタイプ', 'ギニアス・サハリン技術少将がサイド３よりパーツを運び、アプサラス護衛のために組み立てた２機以外に唯一実戦で使用された機体。オデッサにて無名のパイロットに使用されたが、その後キシリアによりシャアに廻されたと言われる。残念ながらシャアが宇宙に戻ってしまった為、実際にシャア自身が搭乗したことは無い。', 380, 300, 15, 82, 52, 12, 0, 120, 0, 80, 0, 0, 20, 2, -5, -3, 5, '', 0, 36, 'MS-07H(CA).png', 400);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (870, 'クワトロ専用ジム改', 'クワトロ・バジーナがエゥーゴに参画した際、初めて搭乗した機体である。性能的には機体のレスポンスが向上するよう調節されている程度で、カラーリングを除けば特に一般機と大差ない。エゥーゴに参加したばかりのクワトロが同カラーに塗装しているのを見て、古参のエゥーゴパイロットからは「赤い彗星でも気取っているのかね」と冷ややかな目で見られていたのだが、その後繰り返し行なわれた模擬戦でクワトロが格段の戦果を見せたことで、このような声が無くなり、逆に「本物の赤い彗星だ」と言われるようになってクワトロを苦笑させていたらしい。本人は常に笑って否定していたが、同期に入隊したパイロット複数から「大佐」と呼ばれていたことも、噂話に拍車をかけたとのことである。同機は配備後、しばらくエゥーゴの正面戦力に指定されていたが、その後、急速な発展を遂げるＭＳ開発競争の中で陳腐化したこともあり、ほどなく退役、解体されたとのことである。', 320, 280, 26, 65, 64, 12, 0, 190, 85, 80, 0, 0, 60, 1, 0, 1, 0, '', 0, 30, 'RGM-79C(QV).png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (874, 'グリフォン', 'ジャブローでホワイトベースから降ろされたＲＸ-７５と、同艦にてテスト運営されていたＧアーマーとの組み合わせにより、連邦軍として初のＭＡ的な対艦攻撃機として甦った。本機にはコードネームとして「Ｇアタッカー」の名が与えられたが、パイロットとなったポリース・イワノビッチ・ゴルゴーノ中尉は、２種の機体を組み合わせた本機を「古代神話に登場するライオン（＝ガンタンク）と鷲（Ｇアーマー）の合成獣」に見立てて「グリフォン」と呼んでいた。', 360, 350, 34, 60, 60, 20, 0, 100, 0, 0, 80, 0, 25, 0, -1, 3, 3, '6', 0, 35, 'RX-75G.png', 400);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (875, '先行量産型ハイザック', 'ティターンズによってテストされ、ティターンズに実戦配備もされている。本来のカラーは緑主体。脚部などに若干の違いはあるものの、基本的にハイザックと変わりはない。これはジオン残党の駆るＦ２型ザクＩＩと激戦を繰り広げたマーフィー小隊仕様の先行量産型ハイザック。', 390, 300, 32, 68, 55, 15, 0, 0, 0, 100, 0, 0, 10, 0, -1, 0, 0, '', 0, 28, 'YRMS-106.png', 750);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (876, 'ガンダムヘイズル予備機', 'ガンダムＴＲ-１ヘイズルの交換パーツ用の予備機としてアスワンに配備されたもので、通常戦闘への参加は想定されていない。', 420, 400, 40, 80, 64, 30, 150, 180, 160, 140, 0, 0, 0, 2, 0, 1, 0, '', 0, 36, 'RGM-79Q(HH).png', 1500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (881, 'バルトフェルド専用バクゥ改修タイプ', '「砂漠の虎」アンディ・バルトフェルドがラゴゥ配備前に乗機としていたラゴゥのプロトタイプ。頭部に装備された鋭い牙と前脚の爪、黄色と黒の塗り分けといった「虎」風意匠は、虎縞のパイロットスーツに身を包み戦場に赴くバルトフェルドならでは。', 420, 500, 40, 90, 50, 20, 250, 250, 130, 50, 50, -3, 50, 5, -1, -4, 0, '2##4', 0, 44, 'TMF-A-802(AB).png', 1500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (883, 'マスターアッガイ', 'ウォンと喧嘩別れした東方不敗に突如回された機体（嘘）。しかし、そこはマスター。何に乗っても強いのであった。', 300, 200, 21, 40, 48, 10, 10, 20, 30, 0, 0, -5, 200, 0, 2, -1, -1, '4##5', 0, 31, 'm-aggay.png', 200);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (885, 'ギラ・ドーガ重装型', 'ギラ・ドーガを長距離支援用に改修した機体。左腕をランゲブルーノ砲に換装することで火力の向上が図られ、背部に装備された大型シュツルムブースターにより、機動力と行動半径を落とすことなく重武装化を実現している。', 420, 320, 44, 64, 80, 20, 0, 175, 120, 170, 220, 0, 0, 0, -1, 1, 0, '6', 0, 33, 'AMS-119_jyusou.png', 1200);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (887, 'Ｓ・マツナガ専用グフ・カスタム', '一説によるとシャア専用に作られていたグフを急遽シン・マツナガに渡したものだとも言われている。だがシン・マツナガがグフに搭乗したという正式な記録は残っていない上にパーソナルカラーまで全然異なっている。誤認にしてもひどい話である。真実はわからないが、エースパイロット用のグフが存在したことは確かなようである。', 390, 390, 39, 97, 65, 15, 100, 150, 150, 100, 0, 0, 50, 5, 0, -4, 1, '4', 0, 41, 'MS-07B3(SM).png', 500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (888, 'Ｓ・マツナガ専用ザクＩ', '旧ザクの別塗装カスタムバージョン。「白狼」の異名を持つシン・マツナガの搭乗機。開戦直後の一週間戦争で他のエース達と共に大戦果を上げたことで有名な機体である。', 345, 228, 19, 52, 52, 12, 10, 35, 40, 0, 0, 0, 10, 2, -2, 3, 0, '', 0, 29, 'MS-05(SM).png', 150);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (889, 'ガトー専用ザクＩ', '旧ザクの別塗装カスタムバージョン。「ソロモンの悪夢」の異名を持つアナベル・ガトーの搭乗機である。', 340, 228, 19, 52, 52, 12, 10, 35, 40, 0, 0, 0, 10, 2, -2, 3, 0, '', 0, 28, 'MS-05(AG).png', 150);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (890, 'レズン専用ギラ・ドーガ重装型', 'ギラ・ドーガを長距離支援用に改修した機体のレズン専用機。背部に装備された大型シュツルムブースターにより、機動力と行動半径を落とすことなく重武装化を実現している。', 590, 460, 54, 90, 98, 20, 180, 200, 160, 165, 165, 0, 30, 0, -1, 1, 0, '6', 0, 44, 'AMS-119(R)jyuusou.png', 2500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (891, 'シャア専用グフ・カスタム', 'ガルマ戦死の混乱のせいで行方不明になったシャア専用にカスタムされたグフ。ホワイトベースを追って地上に降りたシャアの為、ガルマにより作成を命令されていたのだが、その後すぐにガルマが戦死したのとシャアの一時的な行方不明により結局シャアの手に渡ることもなく、その後どうなったかの記録も残っていない。尚、グフの外見には二通りの記録があり、これはそのうちのひとつである。', 380, 390, 30, 99, 65, 15, 100, 150, 150, 100, 0, 0, 50, 5, 0, -4, 1, '4', 0, 41, 'MS-07B3(CA).png', 500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (892, 'シャア専用ケンプファー', 'ゲルググと共にシャアの為に用意されようとした機体。キシリアにどちらが良いか尋ねられたシャアは汎用性の高いゲルググを選んだ。との記録が残っている。', 400, 460, 35, 105, 75, 18, 0, 200, 200, 200, 0, 0, 50, 4, -1, 1, -2, '4', 0, 43, 'MS-18E(CA).png', 800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (893, 'キャスバル専用高機動型ガンダム', 'ネオジオンがキャスバル総帥のためにガンダムの機動性を追及すべく作成した機体。パイロットが失神するほどの瞬間加速性能を得たが作戦可能時間がその分犠牲になってしまった。', 300, 270, 20, 110, 60, 20, 230, 240, 210, 210, 200, 0, 75, 3, -2, 3, 0, '-14##127', 0, 38, 'RX-78-2(HM)(CA).png', 1000);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (894, 'ドズル専用ケンプファー', 'ザビ家次男、ドズル・ザビ中将のために用意されたと言われるケンプファーである。', 480, 600, 48, 62, 75, 18, 0, 200, 200, 200, 0, 0, 50, 4, -1, 1, -2, '4', 0, 44, 'MS-18E(DZ).png', 800);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (900, 'ジム改高機動型', 'ジムＩＩの評価試験機として、ティターンズがジム改をベースに開発した試作ＭＳ。各センサーや、スラスター等の強化が行われている。データ収集の為、Ｔ３部隊に配備されている。', 300, 280, 27, 78, 68, 12, 0, 190, 85, 80, 0, 0, 15, 1, 0, 1, 0, '', 0, 30, 'RGM-79CR.png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (901, 'ジム・スナイパーＩＩＩ', 'ジムＩＩの評価試験機として、ティターンズの実験部隊に配備された試作ＭＳ。ジム改高機動型からの換装により狙撃型に仕様変更した機体で、バイザー・センサーの強化版を装着している。', 300, 300, 27, 54, 82, 14, 0, 190, 85, 80, 0, 0, 15, 1, 0, 1, 0, '', 0, 30, 'RGM-79SR.png', 600);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (902, 'ＥＷＡＣジム', 'ジム・カスタムをベースに電子戦用に改修された機体。背部にブロック状の各種ＥＷＡＣユニットを装備する。', 280, 250, 21, 60, 90, 12, 0, 100, 40, 40, 0, 0, 15, 2, -1, 0, 0, '', 0, 29, 'RGM-79EW.png', 400);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (903, 'ジン水中戦仕様', 'ジンを再設計して開発された水陸両用ＭＳ。陸戦能力の強化も計られている。', 300, 225, 22, 50, 42, 13, 0, 80, 0, 40, 0, -1, 10, 1, 4, -4, -3, '5', 0, 28, 'UWMF-S-1.png', 250);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (906, 'バクゥ戦術偵察タイプ', 'バクゥから兵装に必要な部分を極力排除し、燃料スペースの増加、機体各部に探知システムを装着する、など偵察機としての改造を施した機体。', 410, 540, 30, 82, 70, 20, 150, 240, 130, 50, 70, -1, 20, 5, -1, -4, 0, '', 0, 43, 'TMF-TR-2.png', 1200);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (907, 'ヨーロッパ戦線仕様グフ', 'ヨーロッパで使用されたグフ重装型のひとつ。若干のチューンアップはあるものの基本的にグフ重装型と変わるところは無い。', 300, 260, 27, 54, 58, 12, 0, 100, 0, 60, 0, 0, 15, 3, -2, -3, -3, '4', 0, 28, 'MS-07C-3_2.png', 500);
INSERT INTO units (id, name, description, hp, en, armor, mobility, sensor, max_weight, req_intuition, req_piloting, req_short_range, req_mid_range, req_long_range, req_nt_level, req_fame, terrain_ground, terrain_water, terrain_space, terrain_air, tokusyu, custom_cost, unit_lv, image, price) VALUES (910, 'クェス専用サザビー', '量産型サザビー指揮官機をクェスのパーソナルカラーの赤＋白に塗装し、限界にまで出力を上げた機体である。', 650, 500, 50, 100, 87, 40, 245, 260, 240, 240, 240, 3, 100, 1, 0, 3, 0, '2', 0, 54, 'MSN-04(QP).png', 2500);


